import { ResourceIcon, RESOURCE_COLOR, RESOURCE_NAME } from "./icons";
import { RESOURCE_SPACES, SPACE_CAPACITY, tokensIn } from "./resources";
import { Resource, RESOURCES } from "./types";

// The resource market: one track per resource. Each price space shows its price and the
// token pieces on it. Empty slots show as dotted outlines, so the room left is visible.
export function ResourceMarket({
  spaces,
  supply,
  selectable,
  onPick,
  picked,
  compact,
}: {
  spaces: Record<Resource, number[]>;
  supply: Record<Resource, number>;
  // When set, each track can be clicked to pick a resource (used while buying).
  selectable?: boolean;
  onPick?: (r: Resource) => void;
  picked?: Resource | null;
  // Smaller boxes and tighter rows, so the four tracks fit in about 450px.
  compact?: boolean;
}) {
  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: compact ? 4 : 10,
      }}
    >
      {RESOURCES.map((r) => {
        const cap = SPACE_CAPACITY[r];
        const left = tokensIn(spaces, r);
        const isPicked = picked === r;
        const row = (
          <>
            {compact ? (
              <div
                title={`${RESOURCE_NAME[r]}: ${left} on market, ${supply[r]} in supply`}
                style={{
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  width: 30,
                  flex: "none",
                  lineHeight: 1,
                }}
              >
                <ResourceIcon r={r} size={22} />
                <span
                  style={{
                    fontSize: 10,
                    fontWeight: 700,
                    color: RESOURCE_COLOR[r],
                    marginTop: 1,
                  }}
                >
                  {left}
                </span>
              </div>
            ) : (
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 8,
                  minWidth: 118,
                }}
              >
                <ResourceIcon r={r} size={30} />
                <div>
                  <div style={{ fontWeight: 700, color: RESOURCE_COLOR[r] }}>
                    {RESOURCE_NAME[r]}
                  </div>
                  <div className="muted" style={{ fontSize: 12 }}>
                    {left} on market · {supply[r]} in supply
                  </div>
                </div>
              </div>
            )}
            <div
              style={{
                display: "flex",
                flexWrap: compact ? "nowrap" : "wrap",
                gap: compact ? 2 : 4,
                minWidth: 0,
                flex: compact ? "0 1 auto" : undefined,
              }}
            >
              {RESOURCE_SPACES[r].map((price, i) => {
                const n = spaces[r][i];
                const empty = n === 0;
                return (
                  <div
                    key={price}
                    title={`${RESOURCE_NAME[r]} costs ${price} each here: ${n} on the space`}
                    style={{
                      // Compact boxes shrink to fit narrow screens instead of wrapping onto a second line.
                      width: compact ? undefined : 52,
                      flex: compact ? `1 1 ${cap > 1 ? 40 : 30}px` : undefined,
                      minWidth: 0,
                      maxWidth: compact ? (cap > 1 ? 40 : 30) : undefined,
                      borderRadius: compact ? 5 : 8,
                      overflow: "hidden",
                      border: `1px solid ${empty ? "#d6d3d1" : RESOURCE_COLOR[r]}`,
                      background: empty ? "#f5f5f4" : "#fff",
                      opacity: empty ? 0.6 : 1,
                    }}
                  >
                    <div
                      style={{
                        background: empty ? "#d6d3d1" : RESOURCE_COLOR[r],
                        color: "#fff",
                        fontWeight: 800,
                        fontSize: compact ? 11 : 12,
                        lineHeight: compact ? "13px" : undefined,
                        textAlign: "center",
                        padding: compact ? 0 : "1px 0",
                      }}
                    >
                      {price}
                    </div>
                    <div
                      style={{
                        display: "flex",
                        flexWrap: compact ? "wrap" : undefined,
                        justifyContent: "center",
                        gap: compact ? 1 : 2,
                        padding: compact ? "2px 1px" : "4px 2px",
                        minHeight: compact ? 28 : 24,
                        alignItems: "center",
                        alignContent: "center",
                      }}
                    >
                      {Array.from({ length: cap }).map((_, k) =>
                        k < n ? (
                          <ResourceIcon
                            key={k}
                            r={r}
                            size={
                              compact ? (cap > 1 ? 13 : 18) : cap > 1 ? 14 : 18
                            }
                          />
                        ) : (
                          <span
                            key={k}
                            style={{
                              width: compact ? 9 : cap > 1 ? 10 : 12,
                              height: compact ? 9 : cap > 1 ? 10 : 12,
                              margin: compact ? 2 : 0,
                              borderRadius: 999,
                              border: "1px dashed #a8a29e",
                            }}
                          />
                        ),
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </>
        );

        if (selectable && onPick) {
          return (
            <button
              key={r}
              type="button"
              onClick={() => onPick(r)}
              disabled={left === 0}
              style={{
                display: "flex",
                gap: compact ? 6 : 10,
                alignItems: "center",
                flexWrap: "wrap",
                textAlign: "left",
                padding: compact ? 4 : 8,
                borderRadius: 10,
                border: isPicked
                  ? `2px solid ${RESOURCE_COLOR[r]}`
                  : "1px solid #d6d3c4",
                background: isPicked ? "#fffbeb" : "#fff",
                cursor: left === 0 ? "not-allowed" : "pointer",
                opacity: left === 0 ? 0.5 : 1,
              }}
            >
              {row}
            </button>
          );
        }
        return (
          <div
            key={r}
            style={{
              display: "flex",
              gap: compact ? 6 : 10,
              alignItems: "center",
              flexWrap: compact ? "nowrap" : "wrap",
            }}
          >
            {row}
          </div>
        );
      })}
    </div>
  );
}
