import { useState } from "react";
import { LogEntry } from "./types";

export interface RecentLogProps {
  log: LogEntry[];
  limit?: number;
  colorOf?: (pid: string) => string;
}

const CSS = `
.pgs-log { background:#fffdf7; border:1px solid #d6d3c4; border-radius:10px; padding:6px 10px; font-size:12px; }
.pgs-log-head { display:flex; justify-content:space-between; align-items:center; color:#78716c; font-weight:700; font-size:11px; text-transform:uppercase; letter-spacing:.04em; }
.pgs-log-toggle { background:none; border:none; color:#2563eb; cursor:pointer; font-size:12px; padding:0; }
.pgs-log ul { list-style:none; margin:4px 0 0; padding:0; display:flex; flex-direction:column; gap:2px; }
.pgs-log li { display:flex; gap:6px; align-items:baseline; line-height:1.35; }
.pgs-log-dot { width:8px; height:8px; border-radius:50%; flex:none; display:inline-block; }
`;

// A few recent lines, newest first, fading as they age. Toggle shows the whole log.
export function RecentLog({ log, limit = 5, colorOf }: RecentLogProps) {
  const [all, setAll] = useState(false);
  const newest = [...log].reverse();
  const shown = all ? newest : newest.slice(0, limit);
  return (
    <div className="pgs-log">
      <style>{CSS}</style>
      <div className="pgs-log-head">
        <span>Recent</span>
        {log.length > limit && (
          <button
            type="button"
            className="pgs-log-toggle"
            onClick={() => setAll(!all)}
          >
            {all ? "Show fewer" : "Show all"}
          </button>
        )}
      </div>
      <ul>
        {shown.length === 0 && (
          <li style={{ color: "#a8a29e" }}>Nothing yet.</li>
        )}
        {shown.map((e, i) => (
          <li
            key={newest.length - i}
            style={{ opacity: all ? 1 : Math.max(0.4, 1 - i * 0.15) }}
          >
            {colorOf && (
              <span
                className="pgs-log-dot"
                style={{ background: e.by ? colorOf(e.by) : "#d6d3c4" }}
              />
            )}
            <span>{e.text}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}
