import { useCallback, useEffect, useRef, useState } from "react";
import {
  isMuted,
  playPowerGridSound,
  setMuted,
  soundEvents,
  unlockPowerGridAudio,
} from "./sounds";
import { PowerGridState } from "./types";

const DEBOUNCE_MS = 150;

// Plays sounds for changes between consecutive game states. Diffing against the last
// state seen means the optimistic state and the matching server-confirmed state make
// sound once, and a repeated effect run (StrictMode) finds nothing new. The first
// state after loading is silent.
export function usePowerGridSounds(
  state: PowerGridState | undefined,
  me: string,
): { muted: boolean; toggleMute: () => void } {
  const [muted, setMutedState] = useState(isMuted);
  const prev = useRef<PowerGridState | null>(null);

  // Audio can only start after a user gesture.
  useEffect(() => {
    window.addEventListener("pointerdown", unlockPowerGridAudio);
    window.addEventListener("keydown", unlockPowerGridAudio);
    return () => {
      window.removeEventListener("pointerdown", unlockPowerGridAudio);
      window.removeEventListener("keydown", unlockPowerGridAudio);
    };
  }, []);

  // Two state changes within DEBOUNCE_MS (an optimistic state followed quickly by a
  // server one, or a burst of moves) are played as one combined change.
  const base = useRef<PowerGridState | null>(null);
  const latest = useRef<PowerGridState | null>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const meRef = useRef(me);
  meRef.current = me;

  useEffect(() => {
    if (!state || state === prev.current) return;
    const before = prev.current;
    prev.current = state;
    if (!before) return;
    if (!timer.current) base.current = before;
    latest.current = state;
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => {
      timer.current = null;
      soundEvents(base.current, latest.current!, meRef.current).forEach(
        (id, i) => playPowerGridSound(id, i * 0.4),
      );
    }, DEBOUNCE_MS);
  }, [state]);

  useEffect(
    () => () => {
      if (timer.current) clearTimeout(timer.current);
      timer.current = null;
    },
    [],
  );

  const toggleMute = useCallback(() => {
    const next = !isMuted();
    setMuted(next);
    setMutedState(next);
  }, []);

  return { muted, toggleMute };
}
