import { ReactNode } from "react";
import { PlantCard } from "./PlantCard";
import { CoinIcon, HouseIcon } from "./icons";
import { powerSummary, powerTooltip } from "./power";
import { playerStatus, PlayerStatusKind } from "./playerStatus";
import { plantData, storedTotal } from "./plants";
import { PowerGridState } from "./types";

export interface PlayersPanelProps {
  state: PowerGridState;
  me: string;
  nameOf: (pid: string) => string;
  colorOf: (pid: string) => string;
  renderExtra?: (pid: string) => ReactNode;
  // Narrow vertical list for a side rail: name and status on one line, stats below.
  compact?: boolean;
}

const BADGE: Record<PlayerStatusKind, { bg: string; fg: string }> = {
  acting: { bg: "#dcfce7", fg: "#166534" },
  leading: { bg: "#dbeafe", fg: "#1e40af" },
  bidding: { bg: "#dbeafe", fg: "#1e40af" },
  bought: { bg: "#f3e8ff", fg: "#6b21a8" },
  passed: { bg: "#f5f5f4", fg: "#78716c" },
  done: { bg: "#f5f5f4", fg: "#78716c" },
  waiting: { bg: "#f5f5f4", fg: "#a8a29e" },
};

const CSS = `
.pgs-players { background:#fffdf7; border:1px solid #d6d3c4; border-radius:10px; overflow:hidden; }
.pgs-prow { padding:6px 10px; border-top:1px solid #e7e5e4; display:flex; flex-direction:column; gap:4px; }
.pgs-prow:first-of-type { border-top:none; }
.pgs-prow-me { background:#f0fdf4; }
.pgs-prow-top { display:flex; align-items:center; gap:6px; flex-wrap:wrap; }
.pgs-badge { font-size:11px; font-weight:700; border-radius:999px; padding:1px 8px; margin-left:auto; }
.pgs-plants { display:flex; gap:6px; flex-wrap:wrap; padding-top:2px; }
.pgs-cities { display:inline-flex; align-items:center; gap:6px; font-weight:700; }
.pgs-pow { display:inline-flex; align-items:center; gap:2px; border:1px solid #bbf7d0; background:#f0fdf4; color:#166534; border-radius:10px; padding:0 6px; font-size:12px; font-weight:700; white-space:nowrap; }
.pgs-pow-waste { border-color:#fcd34d; background:#fffbeb; color:#b45309; }
.pgs-line { display:contents; }
.pgs-line .pgs-badge { order:9; }
.pgs-compact .pgs-prow { padding:5px 8px; gap:3px; }
.pgs-compact .pgs-prow-top { display:flex; flex-direction:column; align-items:stretch; gap:2px; }
.pgs-compact .pgs-line { display:flex; align-items:center; gap:6px; flex-wrap:wrap; }
.pgs-compact .pgs-line .pgs-badge { order:0; }
`;

function Bolt() {
  return (
    <svg width="11" height="13" viewBox="0 0 12 14" aria-hidden="true">
      <path d="M7.5 0 1 8h4l-1 6 7-9H7z" fill="currentColor" />
    </svg>
  );
}

function CityPower({ state, pid }: { state: PowerGridState; pid: string }) {
  const sum = powerSummary(state, pid);
  return (
    <span className="pgs-cities">
      <span
        title={`${sum.owned} cities owned`}
        style={{ display: "inline-flex", alignItems: "center", gap: 3 }}
      >
        <HouseIcon size={14} /> {sum.owned}
      </span>
      <span
        className={`pgs-pow${sum.wasted ? " pgs-pow-waste" : ""}`}
        title={powerTooltip(sum)}
      >
        <Bolt /> powers {sum.reach}
      </span>
    </span>
  );
}

export function PlayersPanel({
  state: s,
  me,
  nameOf,
  colorOf,
  renderExtra,
  compact,
}: PlayersPanelProps) {
  return (
    <div className={`pgs-players${compact ? " pgs-compact" : ""}`}>
      <style>{CSS}</style>
      {s.order.map((pid, i) => {
        const st = playerStatus(s, pid);
        const b = BADGE[st.kind];
        const owned = s.plants[pid] ?? [];
        return (
          <div
            key={pid}
            className={`pgs-prow${pid === me ? " pgs-prow-me" : ""}`}
          >
            <div className="pgs-prow-top">
              <div className="pgs-line">
                <span
                  style={{
                    color: "#78716c",
                    fontWeight: 700,
                    fontSize: 12,
                    minWidth: 14,
                  }}
                >
                  {i + 1}
                </span>
                <span
                  style={{
                    width: 10,
                    height: 10,
                    borderRadius: "50%",
                    background: colorOf(pid),
                    display: "inline-block",
                  }}
                />
                <strong style={{ color: colorOf(pid) }}>
                  {nameOf(pid)}
                  {pid === me ? " (you)" : ""}
                </strong>
                <span
                  className="pgs-badge"
                  style={{ background: b.bg, color: b.fg }}
                >
                  {st.label}
                </span>
              </div>
              <div className="pgs-line">
                <span
                  style={{
                    display: "inline-flex",
                    alignItems: "center",
                    gap: 3,
                    fontWeight: 700,
                  }}
                >
                  <CoinIcon size={14} /> {s.money[pid] ?? 0}
                </span>
                {renderExtra?.(pid)}
                <CityPower state={s} pid={pid} />
              </div>
            </div>
            {owned.length > 0 && (
              <div className="pgs-plants">
                {owned.map((op) => (
                  <PlantCard
                    key={op.number}
                    n={op.number}
                    size="sm"
                    stored={
                      plantData(op.number).fuel.length > 0
                        ? storedTotal(op.stored)
                        : undefined
                    }
                  />
                ))}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}
