import { PlantData, PlantKind, Resource, Stock } from "./types";

// The 42 power plant cards, from the card table supplied by the user:
// [number, fuel type, fuel cost (tokens to run), cities powered].
// "Nuclear" is uranium. "Fusion" has no fuel cost, so it runs like an eco plant.
type Row = [number, PlantKind, number, number];
const CARDS: Row[] = [
  [3, "oil", 2, 1],
  [4, "coal", 2, 1],
  [5, "hybrid", 2, 1],
  [6, "garbage", 1, 1],
  [7, "oil", 3, 2],
  [8, "coal", 3, 2],
  [9, "oil", 1, 1],
  [10, "coal", 2, 2],
  [11, "uranium", 1, 2],
  [12, "hybrid", 2, 2],
  [13, "eco", 0, 1],
  [14, "garbage", 2, 2],
  [15, "coal", 2, 3],
  [16, "oil", 2, 3],
  [17, "uranium", 1, 2],
  [18, "eco", 0, 2],
  [19, "garbage", 2, 3],
  [20, "coal", 3, 5],
  [21, "hybrid", 2, 4],
  [22, "eco", 0, 2],
  [23, "uranium", 1, 3],
  [24, "garbage", 2, 4],
  [25, "coal", 2, 5],
  [26, "oil", 2, 5],
  [27, "eco", 0, 3],
  [28, "uranium", 1, 4],
  [29, "hybrid", 1, 4],
  [30, "garbage", 3, 6],
  [31, "coal", 3, 6],
  [32, "oil", 3, 6],
  [33, "eco", 0, 4],
  [34, "uranium", 1, 5],
  [35, "oil", 1, 5],
  [36, "coal", 3, 7],
  [37, "eco", 0, 4],
  [38, "garbage", 3, 7],
  [39, "uranium", 1, 6],
  [40, "oil", 2, 6],
  [42, "coal", 2, 6],
  [44, "eco", 0, 5],
  [46, "hybrid", 3, 7],
  [50, "eco", 0, 6], // Fusion
];

const BY_NUMBER: Record<number, Row> = {};
for (const row of CARDS) BY_NUMBER[row[0]] = row;

// The 42 plant numbers.
export const PLANT_NUMBERS: number[] = CARDS.map((row) => row[0]);

// Cards with a plug on the back are the weaker ones, numbered 03 to 15 (rulebook, setup 8).
export const PLUG_NUMBERS: number[] = PLANT_NUMBERS.filter((n) => n <= 15);
// The rest have a socket on the back.
export const SOCKET_NUMBERS: number[] = PLANT_NUMBERS.filter((n) => n > 15);

const FUEL: Record<PlantKind, Resource[]> = {
  coal: ["coal"],
  oil: ["oil"],
  garbage: ["garbage"],
  uranium: ["uranium"],
  hybrid: ["coal", "oil"],
  eco: [],
};

export function plantData(n: number): PlantData {
  const row = BY_NUMBER[n];
  if (!row) throw new Error(`No power plant ${n}`);
  const [number, kind, inputs, cities] = row;
  return { number, kind, fuel: FUEL[kind], inputs, cities };
}

// Tokens a plant can hold: twice the tokens it needs (rulebook, The Power Plants 3).
export function plantCapacity(data: PlantData): number {
  return data.inputs * 2;
}

export function emptyStock(): Stock {
  return { coal: 0, oil: 0, garbage: 0, uranium: 0 };
}

export function storedTotal(stock: Stock): number {
  return stock.coal + stock.oil + stock.garbage + stock.uranium;
}
