import { ReactNode } from "react";
import { CoinIcon, HouseIcon } from "./icons";
import { ownedCities } from "./rules";
import { statusText } from "./statusText";
import { Phase, PowerGridState } from "./types";

export interface StatusBannerProps {
  state: PowerGridState;
  me: string;
  playing: boolean; // game.status === 'started'
  nameOf: (pid: string) => string;
  colorOf: (pid: string) => string;
  children?: ReactNode; // primary action area (buttons)
  trailing?: ReactNode; // right-side slot, e.g. a mute button
}

const PHASES: { id: Phase; label: string }[] = [
  { id: "auction", label: "Auction" },
  { id: "resources", label: "Resources" },
  { id: "build", label: "Build" },
  { id: "bureaucracy", label: "Bureaucracy" },
];

const CSS = `
.pgs-banner { border:1px solid #d6d3c4; border-left:6px solid #a8a29e; border-radius:10px; background:#f5f5f4; padding:8px 12px; display:flex; flex-direction:column; gap:3px; }
.pgs-banner-go { border-color:#86efac; border-left-color:#16a34a; background:#f0fdf4; }
.pgs-banner-top { display:flex; align-items:center; gap:8px; flex-wrap:wrap; font-size:11px; color:#57534e; }
.pgs-track { display:flex; gap:2px; align-items:center; }
.pgs-track span { padding:1px 6px; border-radius:999px; }
.pgs-track .pgs-on { background:#2563eb; color:#fff; font-weight:700; }
.pgs-banner-title { font-size:17px; font-weight:800; margin:0; line-height:1.2; }
.pgs-banner-go .pgs-banner-title { color:#166534; }
.pgs-banner-hint { font-size:13px; color:#57534e; margin:0; }
.pgs-banner-actions { display:flex; gap:6px; flex-wrap:wrap; align-items:center; margin-top:2px; }
`;

export function StatusBanner({
  state: s,
  me,
  playing,
  nameOf,
  children,
  trailing,
}: StatusBannerProps) {
  const t = statusText(s, me, nameOf, playing);
  const cities = ownedCities(s, me).length;
  const over = s.results !== null;
  return (
    <div
      className={`pgs-banner${t.yourTurn ? " pgs-banner-go" : ""}`}
      role="status"
    >
      <style>{CSS}</style>
      <div className="pgs-banner-top">
        {playing && !over && (
          <span className="pgs-track">
            {PHASES.map((p) => (
              <span
                key={p.id}
                className={s.phase === p.id ? "pgs-on" : undefined}
              >
                {p.label}
              </span>
            ))}
          </span>
        )}
        {s.finalRound && !over && (
          <strong style={{ color: "#b91c1c" }}>Final round</strong>
        )}
        {playing && (
          <span>
            Round {s.round} {"·"} Step {s.step}
          </span>
        )}
        <span
          style={{
            marginLeft: "auto",
            display: "inline-flex",
            gap: 8,
            alignItems: "center",
            fontWeight: 700,
            fontSize: 13,
            color: "#1c1917",
          }}
        >
          <span
            style={{ display: "inline-flex", alignItems: "center", gap: 3 }}
          >
            <CoinIcon size={14} /> {s.money[me] ?? 0}
          </span>
          <span
            style={{ display: "inline-flex", alignItems: "center", gap: 3 }}
          >
            <HouseIcon size={14} /> {cities}
          </span>
          {trailing}
        </span>
      </div>
      <h3 className="pgs-banner-title">{t.title}</h3>
      <p className="pgs-banner-hint">{t.hint}</p>
      {children && <div className="pgs-banner-actions">{children}</div>}
    </div>
  );
}
