// Mute/unmute button, styled like the Ticket to Ride one.
const css = `
.pg-mute { flex: none; width: 34px; height: 34px; border-radius: 50%; border: 1px solid currentColor; background: transparent; color: inherit; font-size: 16px; cursor: pointer; line-height: 1; opacity: 0.8; }
.pg-mute:hover { opacity: 1; }
`;

export function SoundToggle({
  muted,
  onToggle,
}: {
  muted: boolean;
  onToggle: () => void;
}) {
  const label = muted ? "Turn sounds on" : "Turn sounds off";
  return (
    <>
      <style>{css}</style>
      <button
        type="button"
        className="pg-mute"
        onClick={onToggle}
        title={label}
        aria-label={label}
        aria-pressed={muted}
      >
        {muted ? "\u{1F507}" : "\u{1F50A}"}
      </button>
    </>
  );
}

export default SoundToggle;
