import { PowerGridState } from "./types";

export interface StatusText {
  title: string;
  hint: string;
  yourTurn: boolean;
}

// Pure text for the status banner. `yourTurn` means the viewer has an action to take.
export function statusText(
  s: PowerGridState,
  me: string,
  nameOf: (pid: string) => string,
  playing: boolean,
): StatusText {
  if (s.results) {
    const winners = s.results.winners;
    const names = winners.map(nameOf).join(" and ");
    return {
      title: "Game over",
      hint:
        winners.length === 0
          ? "No winner."
          : winners.includes(me)
            ? `You won! (${names})`
            : `${names} won.`,
      yourTurn: false,
    };
  }
  if (!playing)
    return {
      title: "Waiting to start",
      hint: "The host starts the game when everyone is in.",
      yourTurn: false,
    };

  const wait = (pid: string | null, what: string): StatusText => ({
    title: pid ? `Waiting for ${nameOf(pid)}…` : "Waiting…",
    hint: what,
    yourTurn: false,
  });

  if (s.pendingScrap !== null) {
    return s.pendingScrap === me
      ? {
          title: "Scrap a plant",
          hint: "You have too many plants. Pick one to scrap.",
          yourTurn: true,
        }
      : wait(s.pendingScrap, "They have too many plants and must scrap one.");
  }

  if (s.phase === "auction" && s.auction) {
    const bidder = s.auction.active[s.auction.turn];
    if (bidder === me) {
      return {
        title: "Bid or drop out",
        hint: `Plant ${s.auction.plant} is at ${s.auction.price}.`,
        yourTurn: true,
      };
    }
    return wait(bidder ?? null, `Bidding on plant ${s.auction.plant}.`);
  }

  const mine = s.current === me;
  switch (s.phase) {
    case "auction":
      return mine
        ? {
            title: "Your turn: pick a plant to auction",
            hint:
              s.round === 1
                ? "Click a blue plant. You must buy one this round."
                : "Click a blue plant, or pass.",
            yourTurn: true,
          }
        : wait(s.current, "Choosing a plant to auction.");
    case "resources":
      return mine
        ? {
            title: "Buy resources",
            hint: "Fuel your plants, then click Done.",
            yourTurn: true,
          }
        : wait(s.current, "Buying resources.");
    case "build":
      return mine
        ? {
            title: "Build cities (click the map)",
            hint: "Then click Done building.",
            yourTurn: true,
          }
        : wait(s.current, "Building cities.");
    case "bureaucracy":
      return mine
        ? {
            title: s.finalRound
              ? "Final round: choose plants to run"
              : "Choose plants to run",
            hint: s.finalRound
              ? "Power as many cities as you can."
              : "Run plants to earn income.",
            yourTurn: true,
          }
        : wait(s.current, "Choosing plants to run.");
  }
}
