import {
  CSSProperties,
  ReactElement,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  BOARD_HEIGHT,
  BOARD_WIDTH,
  CITIES,
  CityData,
  EDGES,
  REGIONS,
} from "./map/map";
import { cheapestPath, edgeCost, edgeKey } from "./paths";
import {
  distancesFrom,
  housesAllowed,
  ownedCities,
  step2Cities,
} from "./rules";
import { PowerGridState } from "./types";

// Interactive map of Germany. Only the regions in play are live; the rest are drawn faded.
//
// Interaction:
//   Mouse: hover a city or road for details; click a buildable city to build.
//   Touch: the first tap on a city only inspects it (shows the tooltip and route). Tapping the same
//          city again builds if canBuild(cityId). Tapping the empty map clears the selection.
//   Keyboard: cities are focusable; focus shows the tooltip, Enter or Space builds.

export interface PowerGridMapProps {
  state: PowerGridState;
  me: string;
  colorOf: (pid: string) => string;
  nameOf: (pid: string) => string;
  canBuild: (cityId: string) => boolean;
  onBuild: (cityId: string) => void;
  busy?: boolean;
}

const SLOT_PRICE = [10, 15, 20];
const regionInk = (id: string) =>
  REGIONS.find((r) => r.id === id)?.ink ?? "#1c1917";
const CITY_BY_ID: Record<string, CityData> = Object.fromEntries(
  CITIES.map((c) => [c.id, c]),
);

// Road tiers: the road itself encodes its cost (cheap green, middling amber, dear red).
const TIERS = [
  { max: 8, road: "#5aa06f", badge: "#2f7a49", width: 5, label: "0-8" },
  { max: 14, road: "#e0a030", badge: "#a86a0c", width: 7, label: "9-14" },
  { max: 99, road: "#cf4a35", badge: "#a8281b", width: 9, label: "15-21" },
];
function tierOf(cost: number) {
  return TIERS.find((t) => cost <= t.max) ?? TIERS[2];
}

const SLOT_W = 24; // horizontal space per house slot
const NODE_H = 38;
const LEGEND_H = 26; // strip under the board that holds the legend (never overlaps cities)

const CSS = `
.pgm-tip { position: absolute; z-index: 5; pointer-events: none; box-sizing: border-box; padding: 12px 14px; border-radius: 10px;
  background: rgba(28,25,23,0.95); color: #fafaf9; font-size: 15px; line-height: 1.4; box-shadow: 0 6px 20px rgba(0,0,0,0.35); overflow: hidden; }
.pgm-tip h4 { margin: 0 0 4px; font-size: 18px; display: flex; justify-content: space-between; gap: 8px; }
.pgm-tip .pgm-sub { color: #d6d3d1; font-size: 14px; }
.pgm-row { display: flex; justify-content: space-between; gap: 10px; font-size: 17px; }
.pgm-row b { font-size: 20px; }
.pgm-total { border-top: 1px solid rgba(255,255,255,0.25); margin-top: 4px; padding-top: 4px; font-weight: 700; font-size: 20px; }
.pgm-note { margin-top: 6px; padding: 6px 8px; border-radius: 6px; font-size: 14px; }
.pgm-bad { background: rgba(220,38,38,0.28); }
.pgm-info { background: rgba(255,255,255,0.12); }
.pgm-ok { background: rgba(22,163,74,0.32); }
.pgm-dot { display: inline-block; width: 10px; height: 10px; border-radius: 5px; border: 1.5px solid #fff; margin-right: 5px; vertical-align: middle; }
.pgm-label { color: #fbbf24; font-size: 12px; text-transform: uppercase; letter-spacing: 0.04em; margin: 6px 0 2px; }
.pgm-legend { position: absolute; left: 0; right: 0; bottom: 0; height: ${LEGEND_H}px; pointer-events: none; display: flex; gap: 4px 14px; flex-wrap: wrap;
  overflow: hidden; justify-content: center; align-items: center; font-size: 12px; color: #44403c; white-space: nowrap; }
.pgm-legend i { display: inline-block; width: 16px; height: 10px; border-radius: 5px; margin-right: 4px; vertical-align: middle; border: 2px solid #44403c; background: #fff; box-sizing: border-box; }
.pgm-city:focus { outline: none; }
.pgm-city:focus-visible .pgm-node { stroke: #2563eb; stroke-width: 4; }
.pgm-pulse { animation: pgm-pulse 1.6s ease-in-out infinite; }
@keyframes pgm-pulse { 0%, 100% { opacity: 0.95; } 50% { opacity: 0.35; } }
@media (prefers-reduced-motion: reduce) { .pgm-pulse { animation: none; } }
`;

type Hover =
  { kind: "city"; id: string } | { kind: "edge"; a: string; b: string } | null;

function cityWidth(cap: number): number {
  return 16 + cap * SLOT_W;
}

export function PowerGridMap({
  state,
  me,
  colorOf,
  nameOf,
  canBuild,
  onBuild,
  busy,
}: PowerGridMapProps) {
  const [hover, setHover] = useState<Hover>(null);
  const [pinned, setPinned] = useState<string | null>(null);
  const [size, setSize] = useState({ w: 0, h: 0 });
  const boardRef = useRef<HTMLDivElement>(null);
  const lastPointer = useRef<string>("mouse");

  useLayoutEffect(() => {
    const el = boardRef.current;
    if (!el) return;
    const measure = () =>
      setSize({
        w: el.clientWidth,
        h: Math.max(0, el.clientHeight - LEGEND_H),
      });
    measure();
    if (typeof ResizeObserver === "undefined") {
      window.addEventListener("resize", measure);
      return () => window.removeEventListener("resize", measure);
    }
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  const { round, phase, current } = state;
  // Drop a stale tap selection when the turn moves on.
  useEffect(() => {
    setPinned(null);
  }, [round, phase, current]);

  const cap = housesAllowed(state.step);
  const isPlayer = state.order.includes(me);
  const myCities = useMemo(() => ownedCities(state, me), [state, me]);
  const myDist = useMemo(
    () => (myCities.length ? distancesFrom(myCities, state.regions) : null),
    [myCities, state.regions],
  );
  const live = (id: string) => state.regions.includes(CITY_BY_ID[id].region);
  const liveCities = useMemo(
    () => CITIES.filter((c) => state.regions.includes(c.region)),
    [state.regions],
  );
  // Zoom to the regions in play, so a game with fewer regions gets a bigger map.
  const vb = useMemo(() => {
    const xs = liveCities.map((c) => c.x);
    const ys = liveCities.map((c) => c.y);
    const minX = Math.min(...xs) - 120;
    const maxX = Math.max(...xs) + 120;
    const minY = Math.min(...ys) - 70;
    const maxY = Math.max(...ys) + 90;
    const aspect = BOARD_WIDTH / BOARD_HEIGHT;
    let w = maxX - minX;
    let h = maxY - minY;
    if (w / h < aspect) w = h * aspect;
    else h = w / aspect;
    return { x: (minX + maxX) / 2 - w / 2, y: (minY + maxY) / 2 - h / 2, w, h };
  }, [liveCities]);
  const liveEdges = useMemo(
    () =>
      EDGES.filter(
        (e) =>
          state.regions.includes(CITY_BY_ID[e.from].region) &&
          state.regions.includes(CITY_BY_ID[e.to].region),
      ),
    [state.regions],
  );

  const activeCity =
    hover?.kind === "city" ? hover.id : hover === null ? pinned : null;
  const activeEdge = hover?.kind === "edge" ? hover : null;

  // Route from my network to the inspected city, shown unless I already own it.
  const route = useMemo(() => {
    if (
      !activeCity ||
      !isPlayer ||
      myCities.length === 0 ||
      myCities.includes(activeCity)
    )
      return null;
    const r = cheapestPath(myCities, activeCity, state.regions);
    return r.path.length > 1 ? r : null;
  }, [activeCity, isPlayer, myCities, state.regions]);
  const routeEdges = useMemo(() => {
    const set = new Set<string>();
    if (route)
      for (let i = 1; i < route.path.length; i++)
        set.add(edgeKey(route.path[i - 1], route.path[i]));
    return set;
  }, [route]);

  // Where along each road the cost badge sits: the spot farthest from city nodes and their name labels.
  const badgeT = useMemo(() => {
    const nodeW = cityWidth(cap) + 10;
    const dist = (
      px: number,
      py: number,
      cx: number,
      cy: number,
      hw: number,
      hh: number,
    ) =>
      Math.hypot(
        Math.max(Math.abs(px - cx) - hw, 0),
        Math.max(Math.abs(py - cy) - hh, 0),
      );
    const out: Record<string, number> = {};
    for (const e of liveEdges) {
      const a = CITY_BY_ID[e.from];
      const b = CITY_BY_ID[e.to];
      let best = 0.5;
      let bestScore = -Infinity;
      for (let f = 0.3; f <= 0.7001; f += 0.05) {
        const px = a.x + (b.x - a.x) * f;
        const py = a.y + (b.y - a.y) * f;
        let clear = Infinity;
        for (const c of liveCities) {
          clear = Math.min(
            clear,
            dist(px, py, c.x, c.y, nodeW / 2, NODE_H / 2 + 6),
          ); // node
          clear = Math.min(
            clear,
            dist(px, py, c.x, c.y + NODE_H / 2 + 14, 42, 10),
          ); // name label
        }
        const score = Math.min(clear, 22) - Math.abs(f - 0.5) * 12;
        if (score > bestScore) {
          bestScore = score;
          best = f;
        }
      }
      out[edgeKey(e.from, e.to)] = best;
    }
    return out;
  }, [cap, liveCities, liveEdges]);

  const myColor = colorOf(me);
  const interactive = (id: string) => !busy && canBuild(id);

  const onCityClick = (id: string) => {
    if (lastPointer.current === "touch" && pinned !== id) {
      setPinned(id);
      return;
    }
    if (interactive(id)) onBuild(id);
  };

  // ---- tooltip ----
  const scale = size.w > 0 ? Math.min(size.w / vb.w, size.h / vb.h) : 0;
  const toPx = (x: number, y: number) => ({
    x: scale
      ? (size.w - vb.w * scale) / 2 + (x - vb.x) * scale
      : ((x - vb.x) / vb.w) * size.w,
    y: scale
      ? (size.h - vb.h * scale) / 2 + (y - vb.y) * scale
      : ((y - vb.y) / vb.h) * size.h,
  });

  function tooltipBody(): {
    anchor: { x: number; y: number };
    content: ReactElement;
  } | null {
    if (activeEdge) {
      const a = CITY_BY_ID[activeEdge.a];
      const b = CITY_BY_ID[activeEdge.b];
      const cost = edgeCost(a.id, b.id);
      return {
        anchor: { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 },
        content: (
          <>
            <h4>
              <span>
                {a.name} - {b.name}
              </span>
            </h4>
            <div className="pgm-row">
              <span>Connection</span>
              <b>{cost}</b>
            </div>
            <div className="pgm-sub">
              Linking through this road adds {cost} to the cost of a new house.
            </div>
          </>
        ),
      };
    }
    if (!activeCity) return null;
    const c = CITY_BY_ID[activeCity];
    const houses = state.houses[c.id] ?? [];
    const mine = houses.includes(me);
    const full = houses.length >= cap;
    const slot = SLOT_PRICE[Math.min(houses.length, 2)];
    const s2 = step2Cities(state.order.length);
    const myTurnBuilding = state.phase === "build" && state.current === me;
    const money = state.money[me] ?? 0;
    const conn = isPlayer ? (myDist ? myDist[c.id] : 0) : 0;
    const total = slot + conn;
    const affordable = total <= money;
    const clickable = interactive(c.id);

    let note: ReactElement | null = null;
    if (mine) {
      note = (
        <div className="pgm-note pgm-info">You already have a house here.</div>
      );
    } else if (full) {
      const why =
        state.step === 1
          ? `Full in Step 1: one house per city. A second house (15) opens in Step 2, which starts once a player has ${s2} cities.`
          : state.step === 2
            ? "Full in Step 2: two houses per city. A third house (20) opens in Step 3."
            : "Full: three houses per city is the maximum.";
      note = <div className="pgm-note pgm-bad">{why}</div>;
    } else if (isPlayer && !affordable) {
      note = (
        <div className="pgm-note pgm-bad">
          You can't afford this (need {total}, you have {money}).
        </div>
      );
    } else if (clickable) {
      note = (
        <div className="pgm-note pgm-ok">
          {lastPointer.current === "touch"
            ? "Tap again to build here."
            : "Click to build here."}
        </div>
      );
    } else if (isPlayer) {
      note = (
        <div className="pgm-note pgm-info">
          You can't build right now (only on your turn in the build phase).
        </div>
      );
    }

    return {
      anchor: { x: c.x, y: c.y },
      content: (
        <>
          <h4>
            <span>{c.name}</span>
            <span className="pgm-sub">
              {houses.length} of {cap} houses
            </span>
          </h4>
          {houses.length > 0 ? (
            <div className="pgm-sub">
              {houses.map((pid) => (
                <span
                  key={pid}
                  style={{ marginRight: 8, whiteSpace: "nowrap" }}
                >
                  <span
                    className="pgm-dot"
                    style={{ background: colorOf(pid) }}
                  />
                  {nameOf(pid)}
                  {pid === me ? " (you)" : ""}
                </span>
              ))}
            </div>
          ) : (
            <div className="pgm-sub">No houses yet.</div>
          )}
          {isPlayer && !mine && !full && (
            <>
              <div className="pgm-label">
                {myTurnBuilding
                  ? "Cost to build"
                  : "Would cost if you built now"}
              </div>
              <div className="pgm-row">
                <span>
                  House price (
                  {houses.length === 0
                    ? "1st"
                    : houses.length === 1
                      ? "2nd"
                      : "3rd"}
                  )
                </span>
                <b>{slot}</b>
              </div>
              <div className="pgm-row">
                <span>
                  {myCities.length === 0
                    ? "Connection (first city)"
                    : "Connection from your network"}
                </span>
                <b>{conn}</b>
              </div>
              <div className="pgm-row pgm-total">
                <span>Total</span>
                <span style={{ color: affordable ? "#86efac" : "#fca5a5" }}>
                  {total}{" "}
                  {affordable ? "(you can afford it)" : `(you have ${money})`}
                </span>
              </div>
            </>
          )}
          {note}
        </>
      ),
    };
  }

  const tip = tooltipBody();
  let tipStyle: CSSProperties | null = null;
  if (tip && size.w > 0) {
    const p = toPx(tip.anchor.x, tip.anchor.y);
    const tipW = Math.min(290, size.w - 8);
    const off = 40 * (scale || 1) + 8;
    let left = p.x > size.w / 2 ? p.x - off - tipW : p.x + off;
    left = Math.max(4, Math.min(left, size.w - tipW - 4));
    tipStyle = { left, width: tipW, maxHeight: size.h - 8 };
    if (p.y > size.h / 2) tipStyle.bottom = Math.max(4, size.h - p.y - 20);
    else tipStyle.top = Math.max(4, p.y - 20);
  }

  const clearPin = () => setPinned(null);

  return (
    <div className="pg-board" ref={boardRef}>
      <style>{CSS}</style>
      <svg
        className="pg-svg"
        viewBox={`${vb.x} ${vb.y} ${vb.w} ${vb.h}`}
        preserveAspectRatio="xMidYMid meet"
        style={{ bottom: LEGEND_H, height: `calc(100% - ${LEGEND_H}px)` }}
        role="group"
        aria-label="Map of Germany"
      >
        <defs>
          <filter id="pgm-shadow" x="-30%" y="-30%" width="160%" height="170%">
            <feDropShadow
              dx="0"
              dy="2"
              stdDeviation="2"
              floodColor="#000"
              floodOpacity="0.3"
            />
          </filter>
        </defs>

        {/* Calm base */}
        <rect
          x={vb.x}
          y={vb.y}
          width={vb.w}
          height={vb.h}
          fill="#e8e1cf"
          onClick={clearPin}
        />

        {/* Cities in regions that are not in play: faded and not clickable */}
        <g style={{ pointerEvents: "none" }}>
          {CITIES.filter((c) => !live(c.id)).map((c) => (
            <g key={`off-${c.id}`} opacity={0.55}>
              <circle
                cx={c.x}
                cy={c.y}
                r={9}
                fill="#cfc9be"
                stroke="#8a8478"
                strokeWidth={2}
              />
              <text
                x={c.x}
                y={c.y + 28}
                fontSize={14}
                textAnchor="middle"
                fill="#6b645a"
              >
                {c.name}
              </text>
            </g>
          ))}
        </g>

        {/* Roads: dark casing, inner colour and width by cost tier */}
        {liveEdges.map((e) => {
          const a = CITY_BY_ID[e.from];
          const b = CITY_BY_ID[e.to];
          const key = edgeKey(e.from, e.to);
          const onRoute = routeEdges.has(key);
          const hot =
            activeEdge !== null && edgeKey(activeEdge.a, activeEdge.b) === key;
          const t = tierOf(e.cost);
          const emph = onRoute || hot;
          return (
            <g key={key} style={{ pointerEvents: "none" }}>
              <line
                x1={a.x}
                y1={a.y}
                x2={b.x}
                y2={b.y}
                stroke={emph ? "#fff" : "#2f2a22"}
                strokeWidth={emph ? 20 : t.width + 6}
                strokeLinecap="round"
              />
              <line
                x1={a.x}
                y1={a.y}
                x2={b.x}
                y2={b.y}
                stroke={onRoute ? myColor : hot ? "#2563eb" : t.road}
                strokeWidth={emph ? 12 : t.width}
                strokeLinecap="round"
              />
            </g>
          );
        })}

        {/* Wide invisible hit areas for road hover (under the cities) */}
        {liveEdges.map((e) => {
          const a = CITY_BY_ID[e.from];
          const b = CITY_BY_ID[e.to];
          return (
            <line
              key={`hit-${e.from}-${e.to}`}
              x1={a.x}
              y1={a.y}
              x2={b.x}
              y2={b.y}
              stroke="transparent"
              strokeWidth={30}
              strokeLinecap="round"
              style={{ pointerEvents: "stroke" }}
              onMouseEnter={() =>
                setHover({ kind: "edge", a: e.from, b: e.to })
              }
              onMouseLeave={() => setHover(null)}
              onClick={clearPin}
            />
          );
        })}

        {/* Cities */}
        {liveCities.map((c) => {
          const houses = state.houses[c.id] ?? [];
          const mine = houses.includes(me);
          const full = houses.length >= cap;
          const can = interactive(c.id);
          const active = activeCity === c.id;
          const w = cityWidth(cap) + (mine ? 10 : 0);
          const h = NODE_H + (mine ? 8 : 0);
          const startX = c.x - ((cap - 1) * SLOT_W) / 2;
          const total =
            SLOT_PRICE[Math.min(houses.length, 2)] +
            (isPlayer && myDist ? myDist[c.id] : 0);
          const affordable = total <= (state.money[me] ?? 0);
          return (
            <g
              key={c.id}
              className="pgm-city"
              tabIndex={0}
              role={can ? "button" : "img"}
              aria-label={`${c.name}: ${houses.length} of ${cap} houses${mine ? ", you have a house" : ""}${full ? ", full" : ""}${can ? ", you can build here" : ""}`}
              style={{ cursor: can ? "pointer" : "default" }}
              onPointerDown={(e) => {
                lastPointer.current =
                  e.pointerType === "touch" ? "touch" : "mouse";
              }}
              onMouseEnter={() => setHover({ kind: "city", id: c.id })}
              onMouseLeave={() => setHover(null)}
              onFocus={() => setPinned(c.id)}
              onBlur={() => setPinned((p) => (p === c.id ? null : p))}
              onKeyDown={(e) => {
                if ((e.key === "Enter" || e.key === " ") && interactive(c.id)) {
                  e.preventDefault();
                  onBuild(c.id);
                }
              }}
              onClick={(e) => {
                e.stopPropagation();
                onCityClick(c.id);
              }}
            >
              {mine && (
                <rect
                  x={c.x - w / 2 - 9}
                  y={c.y - h / 2 - 9}
                  width={w + 18}
                  height={h + 18}
                  rx={(h + 18) / 2}
                  fill={myColor}
                  fillOpacity={0.28}
                  stroke={myColor}
                  strokeOpacity={0.55}
                  strokeWidth={2}
                />
              )}
              {can && (
                <rect
                  x={c.x - w / 2 - 6}
                  y={c.y - h / 2 - 6}
                  width={w + 12}
                  height={h + 12}
                  rx={(h + 12) / 2}
                  fill={
                    affordable ? "rgba(34,197,94,0.22)" : "rgba(217,119,6,0.16)"
                  }
                  stroke={affordable ? "#16a34a" : "#b45309"}
                  strokeWidth={affordable ? 3 : 2.5}
                  strokeDasharray={affordable ? undefined : "6 5"}
                />
              )}
              <rect
                className="pgm-node"
                x={c.x - w / 2}
                y={c.y - h / 2}
                width={w}
                height={h}
                rx={h / 2}
                filter="url(#pgm-shadow)"
                fill={full ? "#cfc9be" : "#fffdf7"}
                stroke={mine ? myColor : active ? "#2563eb" : "#1c1917"}
                strokeWidth={mine ? 6 : active ? 4 : 3}
              />
              {mine && (
                <rect
                  x={c.x - w / 2 + 4}
                  y={c.y - h / 2 + 4}
                  width={w - 8}
                  height={h - 8}
                  rx={(h - 8) / 2}
                  fill="none"
                  stroke="#fff"
                  strokeWidth={1.5}
                />
              )}
              {Array.from({ length: cap }, (_, i) => {
                const hx = startX + i * SLOT_W;
                const owner = houses[i];
                const d = `M ${hx - 10} ${c.y} L ${hx} ${c.y - 10} L ${hx + 10} ${c.y} V ${c.y + 9} H ${hx - 10} Z`;
                const mineHouse = owner === me;
                return owner ? (
                  <path
                    key={i}
                    d={d}
                    fill={colorOf(owner)}
                    stroke={mineHouse ? "#1c1917" : "#fff"}
                    strokeWidth={mineHouse ? 2 : 2.5}
                    strokeLinejoin="round"
                    transform={
                      mineHouse
                        ? `translate(${hx} ${c.y}) scale(1.2) translate(${-hx} ${-c.y})`
                        : undefined
                    }
                  />
                ) : (
                  <path
                    key={i}
                    d={d}
                    fill="none"
                    stroke="#a8a29e"
                    strokeWidth={1.8}
                    strokeDasharray="3 2.5"
                  />
                );
              })}
              {mine && (
                <g style={{ pointerEvents: "none" }}>
                  <rect
                    x={c.x - 14}
                    y={c.y - h / 2 - 17}
                    width={28}
                    height={15}
                    rx={7.5}
                    fill={myColor}
                    stroke="#fff"
                    strokeWidth={1.5}
                  />
                  <text
                    x={c.x}
                    y={c.y - h / 2 - 5.5}
                    fontSize={10}
                    fontWeight={800}
                    textAnchor="middle"
                    fill="#fff"
                    stroke="#1c1917"
                    strokeWidth={2.5}
                    paintOrder="stroke"
                  >
                    YOU
                  </text>
                </g>
              )}
            </g>
          );
        })}

        {/* Names: plain text with a halo, below the node */}
        {liveCities.map((c) => {
          const full = (state.houses[c.id] ?? []).length >= cap;
          return (
            <text
              key={`label-${c.id}`}
              x={c.x}
              y={c.y + NODE_H / 2 + 19}
              fontSize={16}
              fontWeight={600}
              textAnchor="middle"
              fill={full ? "#6b645a" : regionInk(c.region)}
              stroke="#e8e1cf"
              strokeWidth={5}
              strokeLinejoin="round"
              paintOrder="stroke"
              style={{ pointerEvents: "none", userSelect: "none" }}
            >
              {c.name}
            </text>
          );
        })}

        {/* Connection cost badges on the roads */}
        {liveEdges.map((e) => {
          const a = CITY_BY_ID[e.from];
          const b = CITY_BY_ID[e.to];
          const key = edgeKey(e.from, e.to);
          const emph =
            routeEdges.has(key) ||
            (activeEdge !== null &&
              edgeKey(activeEdge.a, activeEdge.b) === key);
          const t = tierOf(e.cost);
          const f = badgeT[key] ?? 0.5;
          const mx = a.x + (b.x - a.x) * f;
          const my = a.y + (b.y - a.y) * f;
          const w = emph ? 34 : 26;
          const h = emph ? 28 : 21;
          return (
            <g key={`pill-${key}`} style={{ pointerEvents: "none" }}>
              <rect
                x={mx - w / 2}
                y={my - h / 2}
                width={w}
                height={h}
                rx={h / 2}
                fill={emph ? "#1c1917" : t.badge}
                stroke="#fff"
                strokeWidth={emph ? 2.5 : 2}
              />
              <text
                x={mx}
                y={my + (emph ? 7.5 : 5.5)}
                fontSize={emph ? 21 : 16}
                fontWeight={800}
                textAnchor="middle"
                fill="#fff"
              >
                {e.cost}
              </text>
            </g>
          );
        })}

        {/* Total price: only for the inspected (hovered, focused or tapped) buildable city */}
        {activeCity &&
          interactive(activeCity) &&
          (() => {
            const c = CITY_BY_ID[activeCity];
            const houses = state.houses[c.id] ?? [];
            const total =
              SLOT_PRICE[Math.min(houses.length, 2)] +
              (isPlayer && myDist ? myDist[c.id] : 0);
            const affordable = total <= (state.money[me] ?? 0);
            const w = String(total).length * 13 + 20;
            const cy = c.y - NODE_H / 2 - 24;
            return (
              <g style={{ pointerEvents: "none" }}>
                <rect
                  x={c.x - w / 2}
                  y={cy - 13}
                  width={w}
                  height={26}
                  rx={13}
                  fill={affordable ? "#15803d" : "#b91c1c"}
                  stroke="#fff"
                  strokeWidth={2.5}
                />
                <text
                  x={c.x}
                  y={cy + 7.5}
                  fontSize={20}
                  fontWeight={800}
                  textAnchor="middle"
                  fill="#fff"
                >
                  {total}
                </text>
              </g>
            );
          })()}
      </svg>

      <div className="pgm-legend" aria-hidden="true">
        <span>
          <i
            style={{
              borderColor: myColor,
              borderWidth: 3,
              background: "#fffdf7",
            }}
          />
          your cities
        </span>
        <span>
          <i style={{ borderColor: "#16a34a", background: "#bbf7d0" }} />
          can build
        </span>
        <span>
          road cost
          {TIERS.map((t) => (
            <span key={t.label} style={{ marginLeft: 8 }}>
              <i
                style={{
                  width: 18,
                  height: t.width,
                  borderWidth: 1.5,
                  borderColor: "#2f2a22",
                  background: t.road,
                  borderRadius: 3,
                }}
              />
              {t.label}
            </span>
          ))}
        </span>
      </div>

      {tip && tipStyle && (
        <div className="pgm-tip" style={tipStyle} role="status">
          {tip.content}
        </div>
      )}
    </div>
  );
}
