import { isMuted, setMuted } from "../ticketToRide/sounds";
import { PowerGridState } from "./types";

// Sound effects for Power Grid. Same approach as Ticket to Ride: small Web Audio
// synth sounds, no audio files, and the same shared mute setting.
export { isMuted, setMuted };

export type PowerGridSound =
  | "yourTurn"
  | "nominate"
  | "bid"
  | "fold"
  | "buyPlant"
  | "scrap"
  | "buyResource"
  | "build"
  | "payday"
  | "phase"
  | "newRound"
  | "step"
  | "win"
  | "lose"
  | "gameOver";

const sum = (xs: number[]) => xs.reduce((a, b) => a + b, 0);
const plantCount = (s: PowerGridState) =>
  sum(Object.values(s.plants).map((p) => p.length));
const houseCount = (s: PowerGridState) =>
  sum(Object.values(s.houses).map((h) => h.length));
const marketTokens = (s: PowerGridState) =>
  sum(Object.values(s.resourceSpaces).map((spaces) => sum(spaces)));

function isMyTurn(s: PowerGridState, me: string): boolean {
  if (s.results) return false;
  if (s.pendingScrap) return s.pendingScrap === me;
  if (s.auction) return s.auction.active[s.auction.turn] === me;
  return s.current === me;
}

// The one thing a player just did, judged from the structured state (not the log).
function action(
  prev: PowerGridState,
  next: PowerGridState,
  me: string,
): PowerGridSound | null {
  if (plantCount(next) > plantCount(prev)) return "buyPlant";
  if (plantCount(next) < plantCount(prev)) return "scrap";
  if (houseCount(next) > houseCount(prev)) return "build";
  if (prev.phase === "resources" && marketTokens(next) < marketTokens(prev))
    return "buyResource";
  // Only your own income pays out; other players' paydays are silent for you.
  if (
    prev.phase === "bureaucracy" &&
    (next.money[me] ?? 0) > (prev.money[me] ?? 0)
  )
    return "payday";
  const a = prev.auction;
  const b = next.auction;
  if (!a && b) return "nominate";
  if (a && b && a.plant === b.plant) {
    if (b.price > a.price) return "bid";
    if (b.active.length < a.active.length) return "fold";
  }
  // The auction ended without a sale: everyone dropped out.
  if (a && !b) return "fold";
  return null;
}

// Sounds for what changed between two snapshots, in play order. Calm policy: at most
// two sounds, one for the action and one transition/turn cue. The first snapshot
// (prev === null) is silent.
//  - Game over: the action sound (if any), then win/lose/gameOver.
//  - A transition (step starting, new round, new phase) replaces "your turn", and
//    also replaces your own payday, so the last player's bureaucracy is one cue.
//  - "Your turn" only plays when someone else's action handed the turn to you.
export function soundEvents(
  prev: PowerGridState | null,
  next: PowerGridState,
  me: string,
): PowerGridSound[] {
  if (!prev || prev === next) return [];
  const act = action(prev, next, me);

  if (!prev.results && next.results) {
    const player = me in next.names || me in next.money;
    const end = !player
      ? "gameOver"
      : next.results.winners.includes(me)
        ? "win"
        : "lose";
    return act && act !== "payday" ? [act, end] : [end];
  }

  let cue: PowerGridSound | null = null;
  if (next.step > prev.step) cue = "step";
  else if (next.round > prev.round) cue = "newRound";
  else if (next.phase !== prev.phase) cue = "phase";
  if (!cue && isMyTurn(next, me) && !isMyTurn(prev, me)) cue = "yourTurn";

  if (cue && act === "payday") return [cue];
  return act ? (cue ? [act, cue] : [act]) : cue ? [cue] : [];
}

// --- Synth ---

let ctx: AudioContext | null = null;

function audio(): AudioContext | null {
  if (typeof window === "undefined") return null;
  const Ctor =
    window.AudioContext ??
    (window as unknown as { webkitAudioContext?: typeof AudioContext })
      .webkitAudioContext;
  if (!Ctor) return null;
  if (!ctx) ctx = new Ctor();
  return ctx;
}

// Browsers keep audio suspended until a user gesture; call from a click or keypress.
export function unlockPowerGridAudio() {
  const c = audio();
  if (c && c.state === "suspended") c.resume().catch(() => {});
}

function tone(
  c: AudioContext,
  freq: number,
  start: number,
  duration: number,
  type: OscillatorType = "sine",
  volume = 0.2,
  slideTo?: number,
) {
  const t0 = c.currentTime + start;
  const osc = c.createOscillator();
  const gain = c.createGain();
  osc.type = type;
  osc.frequency.setValueAtTime(freq, t0);
  if (slideTo)
    osc.frequency.exponentialRampToValueAtTime(slideTo, t0 + duration);
  gain.gain.setValueAtTime(0.0001, t0);
  gain.gain.exponentialRampToValueAtTime(volume, t0 + 0.01);
  gain.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);
  osc.connect(gain).connect(c.destination);
  osc.start(t0);
  osc.stop(t0 + duration + 0.02);
}

// Short burst of filtered noise, like a token sliding.
function swish(
  c: AudioContext,
  start: number,
  duration: number,
  volume = 0.15,
) {
  const t0 = c.currentTime + start;
  const buffer = c.createBuffer(
    1,
    Math.floor(c.sampleRate * duration),
    c.sampleRate,
  );
  const data = buffer.getChannelData(0);
  for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
  const src = c.createBufferSource();
  src.buffer = buffer;
  const filter = c.createBiquadFilter();
  filter.type = "bandpass";
  filter.frequency.setValueAtTime(1800, t0);
  filter.frequency.exponentialRampToValueAtTime(4000, t0 + duration);
  const gain = c.createGain();
  gain.gain.setValueAtTime(volume, t0);
  gain.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);
  src.connect(filter).connect(gain).connect(c.destination);
  src.start(t0);
}

// Coin clink: two bright quick notes.
function clink(c: AudioContext, d: number) {
  tone(c, 1568, d, 0.08, "triangle", 0.16);
  tone(c, 2093, d + 0.07, 0.2, "triangle", 0.16);
}

export function playPowerGridSound(id: PowerGridSound, delay = 0) {
  if (isMuted()) return;
  const c = audio();
  if (!c || c.state !== "running") return;
  const d = delay;
  switch (id) {
    case "yourTurn":
      tone(c, 880, d, 0.18, "sine", 0.22);
      tone(c, 1175, d + 0.15, 0.35, "sine", 0.22);
      break;
    case "nominate":
      tone(c, 392, d, 0.1, "triangle", 0.2);
      tone(c, 587, d + 0.09, 0.2, "triangle", 0.2);
      break;
    case "bid":
      clink(c, d);
      break;
    case "fold":
      tone(c, 392, d, 0.3, "sine", 0.18, 220);
      break;
    case "buyPlant":
      tone(c, 110, d, 0.08, "square", 0.12);
      tone(c, 110, d + 0.1, 0.08, "square", 0.12);
      tone(c, 523, d + 0.2, 0.12, "triangle", 0.2);
      tone(c, 784, d + 0.3, 0.2, "triangle", 0.2);
      break;
    case "scrap":
      swish(c, d, 0.2, 0.18);
      tone(c, 220, d, 0.25, "sawtooth", 0.08, 70);
      break;
    case "buyResource":
      swish(c, d, 0.08, 0.12);
      tone(c, 330, d + 0.06, 0.1, "square", 0.08);
      clink(c, d + 0.12);
      break;
    case "build":
      tone(c, 196, d, 0.08, "square", 0.14);
      tone(c, 294, d + 0.08, 0.14, "triangle", 0.2);
      break;
    case "payday":
      clink(c, d);
      clink(c, d + 0.16);
      clink(c, d + 0.32);
      break;
    case "phase":
      tone(c, 659, d, 0.12, "sine", 0.15);
      break;
    case "newRound":
      tone(c, 523, d, 0.12, "triangle", 0.18);
      tone(c, 659, d + 0.1, 0.12, "triangle", 0.18);
      tone(c, 784, d + 0.2, 0.2, "triangle", 0.18);
      break;
    case "step":
      // Rising rumble for the game escalating.
      tone(c, 147, d, 0.5, "sawtooth", 0.08, 294);
      tone(c, 220, d, 0.5, "sawtooth", 0.06, 440);
      break;
    case "win":
    case "gameOver":
      [523, 659, 784, 1047].forEach((f, i) =>
        tone(c, f, d + i * 0.14, 0.3, "triangle", 0.2),
      );
      break;
    case "lose":
      [440, 392, 349, 262].forEach((f, i) =>
        tone(c, f, d + i * 0.18, 0.3, "triangle", 0.18),
      );
      break;
  }
}
