export type Resource = "coal" | "oil" | "garbage" | "uranium";
export const RESOURCES: Resource[] = ["coal", "oil", "garbage", "uranium"];

// "hybrid" plants take either coal or oil. "eco" plants need no fuel.
export type PlantKind = Resource | "hybrid" | "eco";

export interface PlantData {
  number: number;
  kind: PlantKind;
  // Resource types this plant can use. Empty for eco plants.
  fuel: Resource[];
  // Tokens needed to run the plant for one round. Must be used exactly.
  inputs: number;
  // Cities the plant supplies when it runs.
  cities: number;
}

export type Stock = Record<Resource, number>;

export interface OwnedPlant {
  number: number;
  stored: Stock;
}

export type Phase = "auction" | "resources" | "build" | "bureaucracy";

export interface Auction {
  plant: number;
  price: number;
  leader: string; // player id of the current high bidder
  active: string[]; // players still bidding, in turn order
  turn: number; // index into `active` of the player whose bid or fold is due
}

export interface Score {
  id: string;
  cities: number;
  capacity: number; // cities the player can power in the final round
  money: number;
}

export interface Results {
  scores: Score[];
  winners: string[];
}

export interface LogEntry {
  by: string | null; // player id, or null for system messages
  text: string;
}

export interface PowerGridState {
  round: number;
  phase: Phase;
  // Step 1 to 3. Step 2 starts in Bureaucracy; Step 3 when its card is drawn.
  step: 1 | 2 | 3;
  // Turn order for this round.
  order: string[];
  // Player whose turn it is in the current phase.
  current: string | null;
  // Player id -> display name, used in the log.
  names: Record<string, string>;
  money: Record<string, number>;
  // City id -> ids of the players with a house there.
  houses: Record<string, string[]>;
  // Letters of the map regions in play. Cities in other regions can't be built in or linked through.
  regions: string[];
  plants: Record<string, OwnedPlant[]>;
  // Power plant market, sorted ascending. The four lowest form the current market.
  // In Step 3 all of them are biddable and there is no future market.
  market: number[];
  // Plant carrying the discount token during Phase 2 (minimum bid 1), or null.
  discount: number | null;
  // Power plant stack above the Step 3 card.
  deck: number[];
  // Whether the Step 3 card is still in the stack.
  step3InDeck: boolean;
  // Plants placed under the Step 3 card during Steps 1 and 2.
  collected: number[];
  // Resource market: token counts for each price space, indexed like RESOURCE_SPACES.
  resourceSpaces: Record<Resource, number[]>;
  // Used tokens returned to the supply (not the market).
  supply: Stock;
  // Players finished with the current phase (bought, passed, or ended their turn).
  done: string[];
  // Players who bought a plant this round.
  boughtThisRound: string[];
  auction: Auction | null;
  // Player who owns too many plants and must scrap one before play goes on.
  pendingScrap: string | null;
  // The plant bought most recently, which can't be scrapped straight away.
  justBought: number | null;
  // Step 3 card drawn during Bureaucracy: Step 3 starts next round.
  step3Next: boolean;
  // Step 3 card drawn during Phase 2: Step 3 starts before Phase 3.
  step3Arrived: boolean;
  // A player reached the end threshold; this round is the final scoring round.
  finalRound: boolean;
  // Cities each player can power in the final round.
  finalPowered: Record<string, number>;
  results: Results | null;
  log: LogEntry[];
}

export type PowerGridAction =
  | { type: "start" }
  | { type: "nominate"; plant: number }
  | { type: "pass" }
  | { type: "bid"; amount: number }
  | { type: "fold" }
  | { type: "scrap"; plant: number }
  | { type: "buyResource"; plant: number; resource: Resource; units: number }
  | { type: "doneResources" }
  | { type: "buildCity"; city: string }
  | { type: "doneBuild" }
  | { type: "power"; plants: number[] };
