import { plantData, storedTotal } from "./plants";
import { endCities, ownedCities, payout } from "./rules";
import { PowerGridState } from "./types";

export interface Powering {
  plants: number[];
  powered: number;
  income: number;
}

export interface PotentialPowering extends Powering {
  // Sum of the cities all plants can supply, not capped by owned cities.
  capacity: number;
}

export const MAX_TABLE_CITIES = 21;

export function incomeFor(cities: number): number {
  return payout(Math.max(0, cities));
}

export function marginalGain(cities: number): number {
  return payout(cities + 1) - payout(cities);
}

export function incomeTable(): { cities: number; income: number }[] {
  const rows: { cities: number; income: number }[] = [];
  for (let c = 0; c <= MAX_TABLE_CITIES; c++)
    rows.push({ cities: c, income: payout(c) });
  return rows;
}

// Best subset of `candidates` (plant numbers): most cities powered, then fewest plants.
function choose(candidates: number[], owned: number): Powering {
  let best: Powering = { plants: [], powered: 0, income: payout(0) };
  const n = candidates.length;
  for (let mask = 1; mask < 1 << n; mask++) {
    const picked: number[] = [];
    let sum = 0;
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) {
        picked.push(candidates[i]);
        sum += plantData(candidates[i]).cities;
      }
    }
    const powered = Math.min(sum, owned);
    if (
      powered > best.powered ||
      (powered === best.powered &&
        picked.length < best.plants.length &&
        best.plants.length > 0)
    ) {
      best = { plants: picked, powered, income: payout(powered) };
    }
  }
  return best;
}

export function bestPowering(state: PowerGridState, pid: string): Powering {
  const owned = ownedCities(state, pid).length;
  const runnable = (state.plants[pid] ?? [])
    .filter((op) => storedTotal(op.stored) >= plantData(op.number).inputs)
    .map((op) => op.number);
  return choose(runnable, owned);
}

export function potentialPowering(
  state: PowerGridState,
  pid: string,
): PotentialPowering {
  const owned = ownedCities(state, pid).length;
  const all = (state.plants[pid] ?? []).map((op) => op.number);
  const capacity = all.reduce((t, n) => t + plantData(n).cities, 0);
  return { ...choose(all, owned), capacity };
}

const plural = (n: number, one: string, many = one + "s") =>
  `${n} ${n === 1 ? one : many}`;

export function planningAdvice(state: PowerGridState, pid: string): string[] {
  const lines: string[] = [];
  const owned = ownedCities(state, pid).length;
  const mine = state.plants[pid] ?? [];
  const best = bestPowering(state, pid);
  const pot = potentialPowering(state, pid);

  if (mine.length === 0) {
    lines.push(
      "You have no power plants, so you earn only the minimum 10 coins.",
    );
  } else {
    if (owned > pot.capacity) {
      lines.push(
        `You own ${plural(owned, "city", "cities")} but your plants can power ${pot.capacity}: extra cities earn nothing more until you buy more plant capacity`,
      );
    } else if (pot.capacity > owned) {
      lines.push(
        `Your plants could power ${pot.capacity} but you own ${plural(owned, "city", "cities")}: building more cities uses that spare capacity`,
      );
    }
    lines.push(
      `Running all your fuelled plants powers ${plural(best.powered, "city", "cities")} → ${best.income} coins`,
    );
    if (pot.powered > best.powered) {
      lines.push(
        `With full fuel you could power ${pot.powered} → ${pot.income} coins`,
      );
    }
    for (const op of mine) {
      const d = plantData(op.number);
      const have = storedTotal(op.stored);
      if (d.inputs > 0 && have < d.inputs) {
        const what = d.kind === "hybrid" ? "coal or oil" : d.kind;
        lines.push(
          `Plant ${d.number} needs ${d.inputs} ${what} ${d.inputs === 1 ? "token" : "tokens"} to run; it holds ${have} now`,
        );
      }
    }
  }
  const target = Math.min(owned, pot.capacity);
  if (mine.length > 0 && target < pot.capacity) {
    lines.push(
      `Each extra city you power is worth about +${marginalGain(best.powered)} coins`,
    );
  }
  const end = endCities(state.order.length);
  lines.push(`Game ends at ${end} cities (you have ${owned})`);
  return lines;
}
