import { bestPowering, potentialPowering } from "./income";
import { plantData, storedTotal } from "./plants";
import { ownedCities } from "./rules";
import { PowerGridState } from "./types";

export interface PowerSummary {
  // Cities the player owns.
  owned: number;
  // Cities they can power this round with the plants and fuel they hold now.
  powerable: number;
  // Cities all their fuelled plants can supply, even beyond the cities they own.
  reach: number;
  // Cities their plants could supply with full fuel (not capped by owned cities).
  capacity: number;
  // True when they own more cities than they can power right now.
  wasted: boolean;
}

export function powerSummary(state: PowerGridState, pid: string): PowerSummary {
  const owned = ownedCities(state, pid).length;
  const powerable = bestPowering(state, pid).powered;
  const capacity = potentialPowering(state, pid).capacity;
  const reach = (state.plants[pid] ?? [])
    .filter((op) => storedTotal(op.stored) >= plantData(op.number).inputs)
    .reduce((t, op) => t + plantData(op.number).cities, 0);
  return { owned, powerable, reach, capacity, wasted: owned > powerable };
}

export function powerTooltip(sum: PowerSummary): string {
  const { owned, powerable, reach, capacity, wasted } = sum;
  const cap = `Your plants could power up to ${capacity} with full fuel.`;
  if (wasted) {
    return `${owned} cities but your plants & tokens can only power ${powerable} this round; more tokens or a bigger plant would earn more. ${cap}`;
  }
  if (reach > owned) {
    return `Your fuelled plants can power ${reach} cities, ${reach - owned} more than the ${owned} you own. ${cap}`;
  }
  return `Powers ${powerable} of ${owned} cities this round. ${cap}`;
}
