// approximate: they follow the geography, spread out where cities would crowd each other.

export type RegionId = "T" | "N" | "R" | "B" | "Y" | "P";

export interface CityData {
  id: string;
  name: string;
  region: RegionId;
  x: number;
  y: number;
}

export interface EdgeData {
  from: string;
  to: string;
  cost: number;
}

export interface RegionData {
  id: RegionId;
  name: string;
  color: string;
  // Darker shade, used for text.
  ink: string;
}

