export const EDGES: EdgeData[] = LINKS.map(([from, to, cost]) => ({
  from,
  to,
  cost,
}));

export function cityName(id: string): string {
  return CITIES.find((c) => c.id === id)?.name ?? id;
}

export function regionOf(id: string): RegionId | undefined {
  return CITIES.find((c) => c.id === id)?.region;
}

// How many regions are in play for a given number of players.
export function regionCount(playerCount: number): number {
  if (playerCount <= 3) return 3;
  if (playerCount === 4) return 4;
  return 5;
}

// Pairs of regions that touch (some road joins a city of one to a city of the other).
function regionLinks(): Record<string, Set<string>> {
  const adj: Record<string, Set<string>> = {};
  for (const r of REGIONS) adj[r.id] = new Set();
  const reg: Record<string, RegionId> = Object.fromEntries(
    CITIES.map((c) => [c.id, c.region]),
  );
  for (const e of EDGES) {
    const a = reg[e.from];
    const b = reg[e.to];
    if (a !== b) {
      adj[a].add(b);
      adj[b].add(a);
    }
  }
  return adj;
}

export function isConnectedSet(regions: string[]): boolean {
  if (regions.length === 0) return false;
  const adj = regionLinks();
  const seen = new Set<string>([regions[0]]);
  const stack = [regions[0]];
  while (stack.length) {
    const r = stack.pop()!;
    for (const n of Array.from(adj[r])) {
      if (regions.includes(n) && !seen.has(n)) {
        seen.add(n);
        stack.push(n);
      }
    }
  }
  return seen.size === regions.length;
}

// Picks which regions are used: a random set of the right size whose regions all touch each other.
export function pickRegions(
  playerCount: number,
  random: () => number = Math.random,
): RegionId[] {
  const n = regionCount(playerCount);
  const ids = REGIONS.map((r) => r.id);
  const sets: RegionId[][] = [];
  for (let mask = 1; mask < 1 << ids.length; mask++) {
    const set = ids.filter((_, i) => mask & (1 << i));
    if (set.length === n && isConnectedSet(set)) sets.push(set);
  }
  return sets[Math.floor(random() * sets.length)];
}
