import { PowerGridState } from "./types";

export type PlayerStatusKind =
  "acting" | "leading" | "bidding" | "bought" | "passed" | "done" | "waiting";

export interface PlayerStatus {
  kind: PlayerStatusKind;
  label: string;
}

export function playerStatus(s: PowerGridState, pid: string): PlayerStatus {
  if (s.results)
    return {
      kind: "done",
      label: s.results.winners.includes(pid) ? "winner" : "finished",
    };
  if (s.pendingScrap === pid)
    return { kind: "acting", label: "scrapping a plant" };
  const auctioning = s.phase === "auction" && s.auction !== null;
  if (s.phase === "auction" && s.auction) {
    const a = s.auction;
    if (a.active[a.turn] === pid) return { kind: "acting", label: "bid due" };
    if (a.leader === pid)
      return { kind: "leading", label: `high bid ${a.price}` };
    if (a.active.includes(pid)) return { kind: "bidding", label: "bidding" };
  }
  if (s.current === pid && !auctioning)
    return { kind: "acting", label: "acting now" };
  if (s.phase === "auction") {
    if (s.boughtThisRound.includes(pid))
      return { kind: "bought", label: "bought a plant" };
    if (s.done.includes(pid)) return { kind: "passed", label: "passed" };
  } else if (s.done.includes(pid)) {
    return { kind: "done", label: "done" };
  }
  return { kind: "waiting", label: "waiting" };
}
