import { Resource } from "./types";

// Simple vector icons for the game pieces. Each one is drawn on a 24 x 24 grid.

export const RESOURCE_NAME: Record<Resource, string> = {
  coal: "Coal",
  oil: "Oil",
  garbage: "Garbage",
  uranium: "Uranium",
};

export const RESOURCE_COLOR: Record<Resource, string> = {
  coal: "#6b4f2a",
  oil: "#1f2937",
  garbage: "#ca8a04",
  uranium: "#dc2626",
};

export function ResourceIcon({ r, size = 20 }: { r: Resource; size?: number }) {
  const common = {
    width: size,
    height: size,
    viewBox: "0 0 24 24",
    role: "img",
    "aria-label": RESOURCE_NAME[r],
  };
  switch (r) {
    case "coal":
      return (
        <svg {...common}>
          <g stroke="#2a1d10" strokeWidth={0.8} strokeLinejoin="round">
            <polygon points="2,15 7,8 13,10 11,18 4,19" fill="#5b4126" />
            <polygon points="12,9 17,5 22,10 20,17 13,17" fill="#3e2b18" />
            <polygon points="8,19 14,20 13,22 7,22" fill="#4a3320" />
          </g>
        </svg>
      );
    case "oil":
      return (
        <svg {...common}>
          <path
            d="M12 2 C12 2 5 10 5 15 a7 7 0 0 0 14 0 C19 10 12 2 12 2 Z"
            fill="#111827"
            stroke="#000"
            strokeWidth={0.6}
          />
          <path
            d="M9 14 a3 3 0 0 0 2.5 3"
            fill="none"
            stroke="#6b7280"
            strokeWidth={1.2}
            strokeLinecap="round"
          />
        </svg>
      );
    case "garbage":
      return (
        <svg {...common}>
          <rect
            x={5}
            y={4}
            width={14}
            height={17}
            rx={3}
            fill="#eab308"
            stroke="#713f12"
            strokeWidth={1}
          />
          <line x1={5} y1={9} x2={19} y2={9} stroke="#713f12" strokeWidth={1} />
          <line
            x1={5}
            y1={16}
            x2={19}
            y2={16}
            stroke="#713f12"
            strokeWidth={1}
          />
        </svg>
      );
    case "uranium":
      return (
        <svg {...common}>
          <circle
            cx={12}
            cy={12}
            r={10}
            fill="#fef2f2"
            stroke="#dc2626"
            strokeWidth={1}
          />
          <g fill="#dc2626">
            <circle cx={12} cy={7.5} r={3.2} />
            <circle cx={7.4} cy={14.8} r={3.2} />
            <circle cx={16.6} cy={14.8} r={3.2} />
          </g>
          <circle cx={12} cy={12} r={1.8} fill="#fef2f2" />
        </svg>
      );
  }
}

export function EcoIcon({ size = 20 }: { size?: number }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      role="img"
      aria-label="Ecological"
    >
      <path
        d="M4 20 C4 10 10 4 20 4 C20 14 14 20 4 20 Z"
        fill="#16a34a"
        stroke="#14532d"
        strokeWidth={0.8}
      />
      <path
        d="M4 20 L13 11"
        stroke="#14532d"
        strokeWidth={1.2}
        strokeLinecap="round"
      />
    </svg>
  );
}

export function CoinIcon({ size = 16 }: { size?: number }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      role="img"
      aria-label="Coins"
    >
      <circle
        cx={12}
        cy={12}
        r={10}
        fill="#facc15"
        stroke="#a16207"
        strokeWidth={1.5}
      />
      <text
        x={12}
        y={16.5}
        fontSize={13}
        fontWeight={800}
        textAnchor="middle"
        fill="#713f12"
      >
        E
      </text>
    </svg>
  );
}

export function HouseIcon({
  size = 16,
  color = "#44403c",
}: {
  size?: number;
  color?: string;
}) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      role="img"
      aria-label="City"
    >
      <path d="M3 11 L12 3 L21 11 V21 H3 Z" fill={color} />
      <rect x={10} y={14} width={4} height={7} fill="#fffbeb" />
    </svg>
  );
}
