import { useEffect, useRef, useState } from "react";
import {
  canAddToken,
  fillPlan,
  nothingToBuy,
  Pending,
  pendingCost,
  pendingTotal,
  purchaseActions,
  shortPlants,
  slotLayout,
  upcomingPrices,
} from "./buyPlan";
import { CoinIcon, RESOURCE_COLOR, RESOURCE_NAME, ResourceIcon } from "./icons";
import { PlantCard } from "./PlantCard";
import { plantCapacity, plantData, storedTotal } from "./plants";
import { PowerGridAction, PowerGridState, Resource, RESOURCES } from "./types";

export interface BuyResourcesPanelProps {
  state: PowerGridState;
  me: string;
  busy: boolean;
  send: (a: PowerGridAction) => void;
}

const CSS = `
.pgb-panel { background:#fffdf7; border:1px solid #d6d3c4; border-radius:12px; padding:10px; display:flex; flex-direction:column; gap:8px; font-size:14px; }
.pgb-head { display:flex; justify-content:space-between; align-items:center; }
.pgb-title { font-weight:800; font-size:15px; }
.pgb-note { color:#57534e; font-size:12.5px; line-height:1.3; margin:0; }
.pgb-warn { color:#92400e; background:#fef3c7; border:1px solid #fcd34d; border-radius:8px; padding:4px 8px; font-size:12px; margin:0; }
.pgb-plant { border:1px solid #e7e5e4; border-radius:12px; padding:8px; display:flex; gap:12px; align-items:stretch; }
.pgb-plant.pgb-sel { border:1px solid #16a34a; background:#f0fdf4; }
.pgb-card { flex:none; }
.pgb-col { display:flex; flex-direction:column; justify-content:center; gap:10px; flex:1; min-width:0; }
.pgb-row { display:flex; gap:6px; flex-wrap:wrap; align-items:center; }
.pgb-slots { display:flex; gap:5px; flex-wrap:wrap; }
.pgb-slot { width:28px; height:28px; border-radius:999px; border:2px solid #a8a29e; display:flex; align-items:center; justify-content:center; box-sizing:border-box; background:#fff; }
.pgb-slot.pgb-stored { background:#e7e5e4; border-color:#57534e; }
.pgb-slot.pgb-pending { border-style:dashed; border-color:#16a34a; background:#dcfce7; }
.pgb-btn { border:1px solid #a8a29e; background:#fff; border-radius:8px; padding:7px 10px; font-size:14px; font-weight:600; cursor:pointer; font-family:inherit; display:inline-flex; align-items:center; gap:5px; }
.pgb-btn:disabled { opacity:0.4; cursor:not-allowed; }
.pgb-link { border:none; background:none; color:#57534e; text-decoration:underline; padding:7px 4px; }
.pgb-primary { background:#16a34a; border-color:#15803d; color:#fff; font-size:15px; font-weight:800; padding:9px 12px; justify-content:center; }
.pgb-money { display:inline-flex; align-items:center; gap:3px; font-weight:700; }
`;

function Money({ n }: { n: number }) {
  return (
    <span className="pgb-money">
      <CoinIcon size={14} />
      {n}
    </span>
  );
}

export function BuyResourcesPanel({
  state,
  me,
  busy,
  send,
}: BuyResourcesPanelProps) {
  const mine = state.plants[me] ?? [];
  const fuelPlants = mine.filter((p) => plantData(p.number).fuel.length > 0);
  // The plant the pending purchase is for. Only one plant is being filled at a time.
  const [target, setTarget] = useState<number | null>(null);
  const [pending, setPending] = useState<Pending>({});
  // Actions still to send for a purchase that mixes coal and oil on a hybrid plant.
  const [queue, setQueue] = useState<PowerGridAction[]>([]);
  const stateWhenSent = useRef<PowerGridState | null>(null);
  // Round in which the turn was already ended automatically, so Done is sent only once.
  const autoDoneRound = useRef<number | null>(null);

  const active = state.phase === "resources" && state.current === me;
  const nothing = active && nothingToBuy(state, me);

  // The game reducer applies one action at a time and rejects any sent while another is in flight.
  // So a mixed purchase is sent as a chain: the first action goes out on click, and each following
  // one goes out from this effect once a new game state has arrived and the page is no longer busy.
  useEffect(() => {
    if (queue.length === 0) return;
    if (!active) {
      setQueue([]);
      return;
    }
    if (busy || stateWhenSent.current === state) return;
    const [next, ...rest] = queue;
    stateWhenSent.current = state;
    setQueue(rest);
    send(next);
  }, [queue, busy, state, active, send]);

  // When no token could be bought at all, end the turn without asking.
  useEffect(() => {
    if (!active) {
      autoDoneRound.current = null;
      return;
    }
    if (
      !nothing ||
      busy ||
      queue.length > 0 ||
      autoDoneRound.current === state.round
    )
      return;
    autoDoneRound.current = state.round;
    send({ type: "doneResources" });
  }, [active, nothing, busy, queue, state.round, send]);

  if (!active) return null;

  const money = state.money[me] ?? 0;
  const spaces = state.resourceSpaces;
  const queued = queue.length > 0;
  const short = shortPlants(mine);
  const shortText = short
    .map((x) => `Plant ${x.plant}: ${x.have}/${x.need}`)
    .join(", ");

  if (nothing) {
    return (
      <div className="pgb-panel">
        <style>{CSS}</style>
        <div className="pgb-head">
          <span className="pgb-title">Nothing to buy</span>
          <Money n={money} />
        </div>
        {short.length > 0 && (
          <p className="pgb-warn">{shortText}. Can't run next round.</p>
        )}
        {/* If the automatic Done was sent but the turn didn't end, let the player send it themselves. */}
        {!busy && autoDoneRound.current === state.round && (
          <button
            type="button"
            className="btn btn-primary"
            onClick={() => send({ type: "doneResources" })}
          >
            Done
          </button>
        )}
      </div>
    );
  }

  const tp = fuelPlants.find((p) => p.number === target) ?? null;
  const pTotal = tp ? pendingTotal(pending) : 0;
  const cost = tp ? (pendingCost(spaces, pending) ?? 0) : 0;
  const summary = RESOURCES.filter((r) => (pending[r] ?? 0) > 0)
    .map((r) => `${pending[r]} ${r}`)
    .join(" + ");

  const add = (plant: number, r: Resource) => {
    const base: Pending = plant === target ? pending : {};
    setTarget(plant);
    setPending({ ...base, [r]: (base[r] ?? 0) + 1 });
  };

  const buy = () => {
    if (!tp) return;
    const acts = purchaseActions(tp.number, pending);
    if (acts.length === 0) return;
    stateWhenSent.current = state;
    send(acts[0]);
    setQueue(acts.slice(1));
    setPending({});
  };

  return (
    <div className="pgb-panel">
      <style>{CSS}</style>
      <div className="pgb-head">
        <span
          className="pgb-title"
          title="A plant holds twice the tokens it needs to run. The cheapest tokens are taken first."
        >
          Buy resources
        </span>
        <Money n={money} />
      </div>

      {fuelPlants.map((op) => {
        const d = plantData(op.number);
        const cap = plantCapacity(d);
        const have = storedTotal(op.stored);
        const isSel = tp?.number === op.number;
        const pend: Pending = isSel ? pending : {};
        const slots = slotLayout(cap, op.stored, pend);
        const room = cap - have - pendingTotal(pend);
        return (
          <div
            key={op.number}
            className={`pgb-plant${isSel && pTotal > 0 ? " pgb-sel" : ""}`}
          >
            <div className="pgb-card">
              <PlantCard
                n={op.number}
                size={fuelPlants.length > 2 ? "sm" : "lg"}
              />
            </div>
            <div className="pgb-col">
              <div
                className="pgb-slots"
                title={`${have} of ${cap} tokens stored; needs ${d.inputs} to run`}
              >
                {slots.map((sl, i) => (
                  <span
                    key={i}
                    className={`pgb-slot${sl.state === "stored" ? " pgb-stored" : sl.state === "pending" ? " pgb-pending" : ""}`}
                  >
                    {sl.resource && <ResourceIcon r={sl.resource} size={18} />}
                  </span>
                ))}
              </div>
              <div className="pgb-row">
                {d.fuel.map((r: Resource) => {
                  const chk = canAddToken(spaces, op, pend, r, money);
                  const next = upcomingPrices(spaces, r, pend[r] ?? 0, 3);
                  return (
                    <button
                      key={r}
                      type="button"
                      className="pgb-btn"
                      style={{ borderColor: RESOURCE_COLOR[r] }}
                      disabled={busy || queued || !chk.ok}
                      title={
                        chk.ok
                          ? `Add one ${r}. Next prices: ${next.join(", ")}`
                          : chk.reason
                      }
                      aria-label={`Add ${RESOURCE_NAME[r]}`}
                      onClick={() => add(op.number, r)}
                    >
                      <ResourceIcon r={r} size={20} />+ {next[0] ?? ""}
                    </button>
                  );
                })}
                <button
                  type="button"
                  className="pgb-btn"
                  disabled={busy || queued || room <= 0}
                  onClick={() => {
                    setTarget(op.number);
                    setPending(fillPlan(spaces, op, money, pend));
                  }}
                >
                  Fill
                </button>
                {isSel && pTotal > 0 && (
                  <button
                    type="button"
                    className="pgb-btn pgb-link"
                    disabled={busy || queued}
                    onClick={() => setPending({})}
                  >
                    Clear
                  </button>
                )}
              </div>
            </div>
          </div>
        );
      })}

      {short.length > 0 && (
        <p className="pgb-warn">{shortText}. Can't run next round.</p>
      )}

      {pTotal > 0 && (
        <div className="pgb-row" style={{ justifyContent: "space-between" }}>
          <span style={{ fontSize: 13 }}>
            {summary} = <strong>{cost}</strong>
          </span>
          <span className="pgb-note">{money - cost} left</span>
        </div>
      )}

      <div className="pgb-row">
        {pTotal > 0 && (
          <button
            type="button"
            className="pgb-btn pgb-primary"
            style={{ flex: 1 }}
            disabled={busy || queued}
            onClick={buy}
          >
            Buy {pTotal} · {cost}
          </button>
        )}
        <button
          type="button"
          className={`pgb-btn${pTotal > 0 ? "" : " pgb-primary"}`}
          style={pTotal > 0 ? undefined : { flex: 1 }}
          disabled={busy || queued}
          onClick={() => send({ type: "doneResources" })}
        >
          Done
        </button>
      </div>
    </div>
  );
}
