import { Resource, RESOURCES } from "./types";

// Resource market price spaces and tokens per space, from the resource table supplied by the user.
// The number on each space is its price per token. Uranium uses a sparse set of spaces.
export const RESOURCE_SPACES: Record<Resource, number[]> = {
  coal: [1, 2, 3, 4, 5, 6, 7, 8],
  oil: [1, 2, 3, 4, 5, 6, 7, 8],
  garbage: [1, 2, 3, 4, 5, 6, 7, 8],
  uranium: [1, 2, 3, 4, 5, 6, 7, 8, 10, 12, 14, 16],
};

// Tokens each space holds.
export const SPACE_CAPACITY: Record<Resource, number> = {
  coal: 3,
  oil: 3,
  garbage: 3,
  uranium: 1,
};

// Total tokens of each resource in the game. The market's maximum capacity equals this.
export const TOTAL_TOKENS: Record<Resource, number> = {
  coal: 24,
  oil: 24,
  garbage: 24,
  uranium: 12,
};

// Starting market: the spaces that begin filled (rulebook, Preparation 5, and the table's setup).
const START_FILL: Record<Resource, number[]> = {
  coal: [1, 2, 3, 4, 5, 6, 7, 8],
  oil: [3, 4, 5, 6, 7, 8],
  garbage: [7, 8],
  uranium: [14, 16],
};

export function startingSpaces(): Record<Resource, number[]> {
  const spaces = {} as Record<Resource, number[]>;
  for (const r of RESOURCES) {
    spaces[r] = RESOURCE_SPACES[r].map((price) =>
      START_FILL[r].includes(price) ? SPACE_CAPACITY[r] : 0,
    );
  }
  return spaces;
}

// Tokens not on the market at the start. These begin in the supply.
export function startingSupply(
  spaces: Record<Resource, number[]>,
): Record<Resource, number> {
  const supply = {} as Record<Resource, number>;
  for (const r of RESOURCES) supply[r] = TOTAL_TOKENS[r] - tokensIn(spaces, r);
  return supply;
}

export function tokensIn(
  spaces: Record<Resource, number[]>,
  r: Resource,
): number {
  return spaces[r].reduce((sum, n) => sum + n, 0);
}

export function emptySlots(
  spaces: Record<Resource, number[]>,
  r: Resource,
): number {
  return RESOURCE_SPACES[r].length * SPACE_CAPACITY[r] - tokensIn(spaces, r);
}

// Buying takes the cheapest tokens first. Returns null if the market can't supply `units`.
export function quote(
  spaces: Record<Resource, number[]>,
  r: Resource,
  units: number,
): { cost: number; takes: number[] } | null {
  if (units > tokensIn(spaces, r)) return null;
  let left = units;
  let cost = 0;
  const takes = spaces[r].map(() => 0);
  for (let i = 0; i < spaces[r].length && left > 0; i++) {
    const t = Math.min(spaces[r][i], left);
    takes[i] = t;
    cost += t * RESOURCE_SPACES[r][i];
    left -= t;
  }
  return { cost, takes };
}

// Applies a purchase quote to the market.
export function take(
  spaces: Record<Resource, number[]>,
  r: Resource,
  takes: number[],
): void {
  takes.forEach((t, i) => {
    spaces[r][i] -= t;
  });
}

// Resupply: fills empty spaces starting from the most expensive. Returns how many were placed.
export function resupply(
  spaces: Record<Resource, number[]>,
  r: Resource,
  amount: number,
): number {
  let left = amount;
  let placed = 0;
  for (let i = spaces[r].length - 1; i >= 0 && left > 0; i--) {
    const room = SPACE_CAPACITY[r] - spaces[r][i];
    const put = Math.min(room, left);
    spaces[r][i] += put;
    left -= put;
    placed += put;
  }
  return placed;
}
