import { CSSProperties } from "react";
import { EcoIcon, HouseIcon, ResourceIcon, RESOURCE_COLOR } from "./icons";
import { plantCapacity, plantData } from "./plants";
import { PlantKind } from "./types";

// Band colour for each plant kind. Hybrids are split between coal and oil.
function bandStyle(kind: PlantKind): string {
  if (kind === "hybrid")
    return `linear-gradient(135deg, ${RESOURCE_COLOR.coal} 50%, ${RESOURCE_COLOR.oil} 50%)`;
  if (kind === "eco") return "#15803d";
  return RESOURCE_COLOR[kind];
}

export interface PlantCardProps {
  n: number;
  // Small cards are used in the player panel. Large cards are used in the market and choices.
  size?: "lg" | "sm";
  // Minimum bid shown on the card. Defaults to the plant number.
  minBid?: number;
  // Shows the discount token (minimum bid 1).
  discounted?: boolean;
  // Current market (blue outline), future market (faded), or a plain card.
  row?: "current" | "future" | "plain";
  // Tokens on the plant, out of its capacity. Shown on owned plants.
  stored?: number;
  selected?: boolean;
  onClick?: () => void;
  disabled?: boolean;
  title?: string;
}

export function PlantCard({
  n,
  size = "lg",
  minBid,
  discounted = false,
  row = "plain",
  stored,
  selected = false,
  onClick,
  disabled = false,
  title,
}: PlantCardProps) {
  const d = plantData(n);
  const large = size === "lg";
  const w = large ? 112 : 92;
  const h = large ? 128 : 98;
  const outline = selected
    ? "3px solid #16a34a"
    : row === "current"
      ? "3px solid #2563eb"
      : "1px solid #a8a29e";

  const box: CSSProperties = {
    width: w,
    boxSizing: "border-box",
    minHeight: h,
    borderRadius: 12,
    background: "#fffdf7",
    border: outline,
    boxShadow:
      row === "current" || selected
        ? "0 2px 8px rgba(37,99,235,0.25)"
        : "0 1px 3px rgba(0,0,0,0.12)",
    overflow: "hidden",
    display: "flex",
    flexDirection: "column",
    padding: 0,
    textAlign: "left",
    opacity: row === "future" ? 0.7 : 1,
    cursor: onClick && !disabled ? "pointer" : "default",
    fontFamily: "inherit",
    position: "relative",
  };

  const bandH = large ? 38 : 28;
  const band: CSSProperties = {
    background: bandStyle(d.kind),
    color: "#fff",
    height: bandH,
    flex: "none",
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    padding: large ? "0 8px" : "0 5px",
  };

  const discountTip = `Discount token: this plant's minimum bid is 1 coin this round (instead of ${n})`;
  // Fuel and cities are what a player reads most, so they get the biggest type and icons.
  const fuelFont = large ? 22 : 18;
  const fuelIcon = large ? 26 : 20;
  const houseIcon = large ? 24 : 19;

  const body = (
    <>
      <div style={band}>
        <span
          style={{
            background: "#fff",
            color: "#1c1917",
            borderRadius: 999,
            fontWeight: 800,
            fontSize: large ? 18 : 14,
            minWidth: large ? 34 : 26,
            textAlign: "center",
            padding: large ? "2px 6px" : "0 4px",
            lineHeight: large ? "26px" : "20px",
          }}
        >
          {n}
        </span>
        <span
          style={{
            // Long names shrink so they never run into the number bubble.
            fontSize:
              (d.kind === "hybrid" ||
                d.kind === "uranium" ||
                d.kind === "garbage") &&
              large
                ? 9
                : large
                  ? 11
                  : 8,
            fontWeight: 700,
            textTransform: "uppercase",
            letterSpacing: 0.3,
            whiteSpace: "nowrap",
          }}
        >
          {d.kind === "hybrid" ? "Hybrid" : d.kind === "eco" ? "Eco" : d.kind}
        </span>
      </div>

      <div
        style={{
          flex: 1,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          gap: large ? 5 : 3,
          padding: large ? "6px 9px" : "4px 6px",
        }}
      >
        <div
          title="Tokens to run"
          style={{
            display: "flex",
            alignItems: "center",
            gap: 3,
            fontWeight: 800,
            fontSize: fuelFont,
            lineHeight: 1,
          }}
        >
          {d.inputs > 0 ? (
            <>
              {d.inputs}×
              {d.kind === "hybrid" ? (
                <>
                  <ResourceIcon r="coal" size={fuelIcon - 4} />
                  <ResourceIcon r="oil" size={fuelIcon - 4} />
                </>
              ) : (
                <ResourceIcon r={d.fuel[0]} size={fuelIcon} />
              )}
            </>
          ) : (
            <>
              <EcoIcon size={fuelIcon} />
              <span style={{ fontSize: large ? 13 : 11, fontWeight: 700 }}>
                No fuel
              </span>
            </>
          )}
        </div>
        <div
          title="Cities powered"
          style={{
            display: "flex",
            alignItems: "center",
            gap: 4,
            fontWeight: 800,
            fontSize: fuelFont,
            lineHeight: 1,
          }}
        >
          <HouseIcon size={houseIcon} />
          {d.cities}
        </div>
        {stored !== undefined && d.inputs > 0 && (
          <div
            title="Tokens stored"
            style={{
              display: "flex",
              gap: 3,
              alignItems: "center",
              flexWrap: "wrap",
            }}
          >
            {Array.from({ length: plantCapacity(d) }).map((_, i) => (
              <span
                key={i}
                style={{
                  width: large ? 12 : 10,
                  height: large ? 12 : 10,
                  borderRadius: 999,
                  background: i < stored ? "#1c1917" : "transparent",
                  border: "1.5px solid #57534e",
                  boxSizing: "border-box",
                }}
              />
            ))}
          </div>
        )}
      </div>

      {discounted && (
        <span
          title={discountTip}
          aria-label={discountTip}
          style={{
            position: "absolute",
            bottom: 4,
            right: 4,
            background: "#16a34a",
            color: "#fff",
            fontSize: 10,
            fontWeight: 800,
            borderRadius: 6,
            padding: "2px 6px",
            cursor: "help",
          }}
        >
          1 coin
        </span>
      )}
    </>
  );

  const minLabel = minBid ?? n;
  const tip =
    title ??
    `Plant ${n}: ${d.kind}, ${d.inputs} to run, ${d.cities} cities, minimum bid ${minLabel}`;

  if (onClick) {
    return (
      <button
        type="button"
        title={tip}
        onClick={onClick}
        disabled={disabled}
        style={box}
        aria-label={tip}
      >
        {body}
      </button>
    );
  }
  return (
    <div title={tip} style={box} aria-label={tip}>
      {body}
    </div>
  );
}
