import { CSSProperties, useState } from "react";
import { CoinIcon } from "./icons";
import { PlantCard } from "./PlantCard";
import { PowerGridAction, PowerGridState } from "./types";

export interface AuctionPanelProps {
  state: PowerGridState;
  me: string;
  colorOf: (pid: string) => string;
  nameOf: (pid: string) => string;
  busy: boolean;
  send: (a: PowerGridAction) => void;
}

const CSS = `
.pga-panel { background:#fffdf7; border:1px solid #d6d3c4; border-radius:12px; padding:10px; display:flex; flex-direction:column; gap:8px; font-size:14px; }
.pga-head { display:flex; align-items:center; justify-content:space-between; gap:8px; }
.pga-title { font-weight:800; font-size:15px; }
.pga-note { color:#57534e; font-size:12px; line-height:1.3; margin:0; }
.pga-row { display:flex; gap:6px; flex-wrap:wrap; align-items:center; }
.pga-btn { border:1px solid #a8a29e; background:#fff; border-radius:8px; padding:8px 12px; font-size:14px; font-weight:600; cursor:pointer; font-family:inherit; }
.pga-btn:disabled { opacity:0.4; cursor:not-allowed; }
.pga-primary { background:#16a34a; border-color:#15803d; color:#fff; font-size:15px; font-weight:800; padding:8px 14px; flex:1; }
.pga-chip { display:inline-flex; align-items:center; gap:4px; padding:2px 7px; border-radius:999px; border:1px solid #d6d3c4; font-size:12px; font-weight:600; background:#fff; }
.pga-chip.pga-turn { background:#eff6ff; border-color:#2563eb; }
.pga-chip.pga-out { opacity:0.45; text-decoration:line-through; }
.pga-dot { width:9px; height:9px; border-radius:999px; flex:none; }
.pga-stepper { display:inline-flex; align-items:stretch; border:1px solid #a8a29e; border-radius:8px; overflow:hidden; background:#fff; }
.pga-stepper button { border:none; background:#f5f5f4; width:38px; font-size:20px; font-weight:700; cursor:pointer; font-family:inherit; }
.pga-stepper button:disabled { opacity:0.4; cursor:not-allowed; }
.pga-stepper output { min-width:44px; display:flex; align-items:center; justify-content:center; font-weight:800; font-size:20px; }
.pga-money { display:inline-flex; align-items:center; gap:3px; font-weight:700; }
`;

const mini: CSSProperties = {
  display: "inline-flex",
  alignItems: "center",
  gap: 3,
};

function Money({ n }: { n: number }) {
  return (
    <span className="pga-money" style={mini}>
      <CoinIcon size={14} />
      {n}
    </span>
  );
}

function ScrapPrompt({ state, me, nameOf, busy, send }: AuctionPanelProps) {
  const pid = state.pendingScrap!;
  if (pid !== me) {
    return (
      <div className="pga-panel">
        <style>{CSS}</style>
        <p className="pga-note">Waiting for {nameOf(pid)} to scrap a plant.</p>
      </div>
    );
  }
  const options = (state.plants[me] ?? []).filter(
    (p) => p.number !== state.justBought,
  );
  return (
    <div className="pga-panel">
      <style>{CSS}</style>
      <span
        className="pga-title"
        title="You are over the plant limit. A scrapped plant's fuel moves to your other plants where it fits."
      >
        {options.length + 1} plants: tap one to scrap
      </span>
      <div className="pga-row" style={{ alignItems: "flex-start" }}>
        {options.map((p) => (
          <PlantCard
            key={p.number}
            n={p.number}
            size="sm"
            stored={Object.values(p.stored).reduce((a, b) => a + b, 0)}
            disabled={busy}
            title={`Scrap plant ${p.number}`}
            onClick={() => send({ type: "scrap", plant: p.number })}
          />
        ))}
        {state.justBought !== null && (
          <>
            <span
              style={{
                alignSelf: "stretch",
                borderLeft: "2px solid #d6d3c4",
                margin: "0 2px",
              }}
            />
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                gap: 3,
                alignItems: "center",
              }}
            >
              <PlantCard
                n={state.justBought}
                size="sm"
                row="current"
                stored={Object.values(
                  (state.plants[me] ?? []).find(
                    (p) => p.number === state.justBought,
                  )?.stored ?? {},
                ).reduce((a, b) => a + b, 0)}
                title={`Plant ${state.justBought}, the one you just bought. It is kept.`}
              />
              <span className="pga-note" style={{ fontWeight: 700 }}>
                Just bought (kept)
              </span>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

// One inline line of players: colour dot and name, a star on the high bidder, the current decider
// highlighted, and players who are out greyed.
function Bidders({ state, me, colorOf, nameOf }: AuctionPanelProps) {
  const a = state.auction;
  return (
    <div className="pga-row" style={{ gap: 4 }}>
      {state.order.map((pid) => {
        let out = false;
        let turn = false;
        let tip = "";
        if (a) {
          if (a.active.includes(pid)) {
            turn = a.active[a.turn] === pid;
            tip = turn
              ? "Deciding now"
              : pid === a.leader
                ? "High bidder"
                : "Still in";
          } else {
            out = true;
            tip = "Dropped out";
          }
        } else if (state.boughtThisRound.includes(pid)) {
          out = true;
          tip = "Already bought";
        } else if (state.done.includes(pid)) {
          out = true;
          tip = "Passed";
        } else if (pid === state.current) {
          turn = true;
          tip = "Choosing a plant";
        }
        return (
          <span
            key={pid}
            className={`pga-chip${turn ? " pga-turn" : ""}${out ? " pga-out" : ""}`}
            title={tip}
          >
            <span className="pga-dot" style={{ background: colorOf(pid) }} />
            {nameOf(pid)}
            {pid === me ? " (you)" : ""}
            {a && a.leader === pid && !out && (
              <span aria-label="High bidder">{"★"}</span>
            )}
          </span>
        );
      })}
    </div>
  );
}

function PickPlant(props: AuctionPanelProps) {
  const { state, me, nameOf, busy, send } = props;
  const myTurn = state.current === me;
  const round1 = state.round === 1;
  return (
    <div className="pga-panel">
      <style>{CSS}</style>
      <div className="pga-head">
        <span className="pga-title">
          {myTurn ? (
            <>
              Pick a <span style={{ color: "#2563eb" }}>blue plant card</span>
            </>
          ) : (
            <>Waiting for {nameOf(state.current ?? "")} to pick a plant</>
          )}
        </span>
        {myTurn && <Money n={state.money[me] ?? 0} />}
      </div>
      <Bidders {...props} />
      {myTurn && (
        <div className="pga-row">
          <button
            type="button"
            className="pga-btn"
            disabled={busy || round1}
            title="Skip buying a plant this round. You can't come back to the auction."
            onClick={() => send({ type: "pass" })}
          >
            Pass
          </button>
          {round1 && (
            <span className="pga-note">Round 1: everyone buys a plant</span>
          )}
        </div>
      )}
    </div>
  );
}

function Bidding(props: AuctionPanelProps) {
  const { state, me, nameOf, colorOf, busy, send } = props;
  const a = state.auction!;
  const money = state.money[me] ?? 0;
  const [want, setWant] = useState(0);
  const turnPid = a.active[a.turn];
  const myTurn = turnPid === me;
  const min = a.price + 1;
  const canBid = money >= min;
  const amt = Math.min(Math.max(want, min), Math.max(money, min));
  const iLead = a.leader === me;

  return (
    <div className="pga-panel">
      <style>{CSS}</style>
      <div
        className="pga-row"
        style={{ flexWrap: "nowrap", alignItems: "center", gap: 10 }}
      >
        <div style={{ flex: "none" }}>
          <PlantCard
            n={a.plant}
            size="lg"
            discounted={state.discount === a.plant}
          />
        </div>
        <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
          <span style={{ fontSize: 15 }}>
            High bid <strong style={{ fontSize: 26 }}>{a.price}</strong>
          </span>
          <span style={{ fontSize: 13 }}>
            by{" "}
            <strong style={{ color: colorOf(a.leader) }}>
              {nameOf(a.leader)}
              {iLead ? " (you)" : ""}
            </strong>
          </span>
        </div>
      </div>

      <Bidders {...props} />

      {myTurn ? (
        <>
          <div className="pga-row">
            <span className="pga-stepper">
              <button
                type="button"
                aria-label="Lower bid"
                disabled={busy || amt <= min}
                onClick={() => setWant(amt - 1)}
              >
                {"−"}
              </button>
              <output aria-label="Your bid">{amt}</output>
              <button
                type="button"
                aria-label="Raise bid"
                disabled={busy || amt >= money}
                onClick={() => setWant(amt + 1)}
              >
                +
              </button>
            </span>
            {[5, 10].map((n) => (
              <button
                key={n}
                type="button"
                className="pga-btn"
                disabled={busy || a.price + n > money}
                onClick={() => setWant(a.price + n)}
              >
                +{n}
              </button>
            ))}
          </div>
          <div className="pga-row">
            <button
              type="button"
              className="pga-btn pga-primary"
              disabled={busy || !canBid}
              title="If you win you pay your last bid."
              onClick={() => send({ type: "bid", amount: amt })}
            >
              Bid {amt}
              <span style={{ fontSize: 11, fontWeight: 500 }}>
                {" "}
                · {money - amt} left
              </span>
            </button>
            <button
              type="button"
              className="pga-btn"
              disabled={busy || iLead}
              title={
                iLead
                  ? "You hold the high bid"
                  : "Out for this plant. You can still bid in the next auction."
              }
              onClick={() => send({ type: "fold" })}
            >
              Drop out
            </button>
          </div>
          {!canBid && (
            <span className="pga-note">Can&apos;t outbid {a.price}</span>
          )}
        </>
      ) : (
        <span className="pga-note">Waiting for {nameOf(turnPid ?? "")}</span>
      )}
    </div>
  );
}

export function AuctionPanel(props: AuctionPanelProps) {
  const { state } = props;
  if (state.pendingScrap !== null) return <ScrapPrompt {...props} />;
  if (state.phase !== "auction") return null;
  return state.auction ? <Bidding {...props} /> : <PickPlant {...props} />;
}
