import { CoinIcon, HouseIcon } from "./icons";
import {
  bestPowering,
  incomeFor,
  incomeTable,
  marginalGain,
  planningAdvice,
  potentialPowering,
} from "./income";
import { ownedCities } from "./rules";
import { PowerGridState } from "./types";

export interface IncomePlannerProps {
  state: PowerGridState;
  pid: string;
  compact?: boolean;
  // Only the payment table and its legend, without the headline or advice.
  chartOnly?: boolean;
}

const CSS = `
.pgi-panel{background:#fffdf7;border:1px solid #d6d3c4;border-radius:8px;padding:8px 10px;font-size:13px;color:#44403c;max-width:100%;box-sizing:border-box}
.pgi-head{display:flex;align-items:center;gap:6px;flex-wrap:wrap;font-weight:600}
.pgi-sub{font-size:12px;color:#78716c;margin-top:2px}
.pgi-strip{display:grid;grid-template-columns:repeat(6,1fr);gap:3px;margin:8px 0}
.pgi-cell{position:relative;text-align:center;border:1px solid #e7e5d8;border-radius:5px;padding:3px 0 4px;line-height:1.15;cursor:default;box-sizing:border-box;min-width:0}
.pgi-c{font-size:11px;color:#78716c}
.pgi-v{font-size:14px;font-weight:700}
.pgi-own{box-shadow:inset 0 0 0 2px #44403c}
.pgi-now{outline:2px solid #15803d;outline-offset:-1px}
.pgi-cap{border-bottom:3px solid #b45309}
.pgi-legend{display:flex;flex-wrap:wrap;gap:8px;font-size:11px;color:#57534e}
.pgi-key{display:inline-block;width:10px;height:10px;border-radius:2px;margin-right:3px;vertical-align:-1px;box-sizing:border-box}
.pgi-advice{margin:6px 0 0;padding-left:16px;font-size:12px;line-height:1.4}
.pgi-chip{display:inline-flex;align-items:center;gap:3px;background:#fef9e0;border:1px solid #e5d98a;border-radius:10px;padding:0 6px;font-size:12px;font-weight:600;color:#713f12;white-space:nowrap}
`;

function heat(income: number): string {
  // Cream to soft amber, scaled by the top of the payout table.
  const t = Math.min(1, Math.max(0, (income - 10) / 140));
  const l = 96 - t * 24;
  return `hsl(45, ${40 + t * 25}%, ${l}%)`;
}

function Headline({ state, pid }: { state: PowerGridState; pid: string }) {
  const best = bestPowering(state, pid);
  const pot = potentialPowering(state, pid);
  return (
    <>
      <div className="pgi-head">
        <span>Run your plants now:</span>
        <span style={{ display: "inline-flex", alignItems: "center", gap: 3 }}>
          {best.powered} <HouseIcon size={14} />
        </span>
        <span>→</span>
        <span style={{ display: "inline-flex", alignItems: "center", gap: 3 }}>
          {best.income} <CoinIcon size={15} />
        </span>
      </div>
      {pot.powered !== best.powered && (
        <div className="pgi-sub">
          Best possible with your plants: {pot.powered} cities → {pot.income}{" "}
          coins
        </div>
      )}
    </>
  );
}

export function IncomePlanner({
  state,
  pid,
  compact,
  chartOnly,
}: IncomePlannerProps) {
  if (compact) {
    const best = bestPowering(state, pid);
    return (
      <div className="pgi-panel" style={{ padding: "4px 8px" }}>
        <style>{CSS}</style>
        <div className="pgi-head" style={{ fontWeight: 600 }}>
          <span>Run your plants now:</span>
          <span>
            {best.powered} {best.powered === 1 ? "city" : "cities"}
          </span>
          <span>→</span>
          <span
            style={{ display: "inline-flex", alignItems: "center", gap: 3 }}
          >
            {best.income} <CoinIcon size={14} />
          </span>
        </div>
      </div>
    );
  }
  const owned = ownedCities(state, pid).length;
  const best = bestPowering(state, pid);
  const pot = potentialPowering(state, pid);
  const capacity = Math.min(pot.capacity, 21);
  const advice = planningAdvice(state, pid);
  return (
    <div className="pgi-panel">
      <style>{CSS}</style>
      {!chartOnly && <Headline state={state} pid={pid} />}
      <div className="pgi-strip" role="table" aria-label="Payment table">
        {incomeTable().map(({ cities, income }) => {
          const cls = ["pgi-cell"];
          if (cities === owned) cls.push("pgi-own");
          if (cities === best.powered) cls.push("pgi-now");
          if (cities === capacity) cls.push("pgi-cap");
          const gain =
            cities > 0
              ? `+${income - incomeFor(cities - 1)} vs ${cities - 1}`
              : "minimum payment";
          const tags = [
            cities === owned ? "cities you own" : "",
            cities === best.powered ? "powered now" : "",
            cities === capacity ? "plant capacity" : "",
          ].filter(Boolean);
          return (
            <div
              key={cities}
              className={cls.join(" ")}
              style={{ background: heat(income) }}
              title={`${cities} cities: ${income} coins (${gain}; next city +${marginalGain(cities)})${tags.length ? " - " + tags.join(", ") : ""}`}
            >
              <div className="pgi-c">{cities}</div>
              <div className="pgi-v">{income}</div>
            </div>
          );
        })}
      </div>
      <div className="pgi-legend">
        <span>
          <span
            className="pgi-key"
            style={{ boxShadow: "inset 0 0 0 2px #44403c" }}
          />
          owned
        </span>
        <span>
          <span className="pgi-key" style={{ border: "2px solid #15803d" }} />
          powered now
        </span>
        <span>
          <span
            className="pgi-key"
            style={{ borderBottom: "3px solid #b45309", background: "#e7e5d8" }}
          />
          plant capacity
        </span>
      </div>
      {!chartOnly && (
        <ul className="pgi-advice">
          {advice.map((l, i) => (
            <li key={i}>{l}</li>
          ))}
        </ul>
      )}
    </div>
  );
}

export function IncomeChip({
  state,
  pid,
}: {
  state: PowerGridState;
  pid: string;
}) {
  const best = bestPowering(state, pid);
  return (
    <span
      className="pgi-chip"
      title={`If this player ran their best plants now: ${best.powered} cities → ${best.income} coins`}
    >
      <style>{CSS}</style>≈ +{best.income} <CoinIcon size={12} />
    </span>
  );
}
