import { CSSProperties, useEffect, useRef, useState } from "react";
import { GameRecord } from "../../types";
import { GameViewProps } from "../types";
import { AuctionPanel } from "./AuctionPanel";
import { BuyResourcesPanel } from "./BuyResourcesPanel";
import { CoinIcon } from "./icons";
import { bestPowering } from "./income";
import { IncomeChip, IncomePlanner } from "./IncomePlanner";
import { CITIES, cityName } from "./map/map";
import { plantData, storedTotal } from "./plants";
import { PlantCard } from "./PlantCard";
import { PlayersPanel } from "./PlayersPanel";
import { PowerGridMap } from "./PowerGridMap";
import { PowerGridRules } from "./PowerGridRules";
import { RecentLog } from "./RecentLog";
import { ResourceMarket } from "./ResourceMarket";
import {
  buildCost,
  housesAllowed,
  MAX_PLAYERS,
  MIN_PLAYERS,
  ownedCities,
  payout,
} from "./rules";
import { SoundToggle } from "./SoundToggle";
import { StatusBanner } from "./StatusBanner";
import { PowerGridAction, PowerGridState } from "./types";
import { usePowerGridSounds } from "./usePowerGridSounds";

// Six colours that stay distinct for most colour-blind players.
export const PLAYER_COLORS = [
  "#2563eb",
  "#dc2626",
  "#16a34a",
  "#d97706",
  "#7c3aed",
  "#db2777",
];

const panel: CSSProperties = {
  background: "#fffdf7",
  border: "1px solid #d6d3c4",
  borderRadius: 12,
  padding: 14,
};

const section: CSSProperties = {
  ...panel,
  display: "flex",
  flexDirection: "column",
  gap: 10,
};
const compactSection: CSSProperties = { ...section, gap: 6, padding: 10 };

// Layout. The DOM is: .pg-main (map card, then plant market + resource market), and .pg-side
// (.pg-action = banner + phase panels + log and rules, then .pg-rail = players + income planner).
// Everything is content-sized. The map keeps its 1440:800 shape, so it can never be squeezed.
//  - Under 1000px wide: one column, in play order: banner and action, map, players, markets, log.
//  - From 1000px wide: map and markets on the left, the side column on the right (page scrolls).
//  - From 1600px wide: three columns: players rail, map and markets, banner and action.
//  - If the window is also tall enough (min-height 1100px, three columns only) the page fits the window exactly: the
//    map takes the height left over, and the rail and the action column scroll on their own.
const PG_CSS = `
.pg-root { display: block; }
.pg-root section { margin: 0; }
.pg-layout { display: flex; flex-direction: column; gap: 12px; }
.pg-main, .pg-side, .pg-action, .pg-act { display: contents; }
.pg-act { order: 0; } .pg-board-card { order: 1; } .pg-rail { order: 2; } .pg-bottom { order: 3; } .pg-extra { order: 4; }
.pg-act, .pg-extra, .pg-rail { display: flex; flex-direction: column; gap: 12px; min-width: 0; }
.pg-board-card { display: flex; flex-direction: column; gap: 6px; padding: 10px 12px; min-width: 0; }
.pg-board-wrap { min-width: 0; overflow-x: auto; }
.pg-board { position: relative; width: 100%; min-width: 720px; aspect-ratio: 1440 / 800; margin: 0 auto; }
.pg-svg { position: absolute; inset: 0; width: 100%; height: 100%; border-radius: 10px; }
.pg-bottom { display: flex; flex-wrap: wrap; gap: 12px; align-items: stretch; min-width: 0; }
.pg-market { min-width: 0; }
.pg-resources { flex: 1 1 auto; min-width: 0; }
.pg-market-row { display: flex; flex-direction: column; gap: 8px; align-items: flex-start; padding: 2px; }
.pg-market-group { display: flex; flex-wrap: wrap; gap: 8px; }
.pg-market-group + .pg-market-group { padding-top: 8px; border-top: 2px solid #d6d3c4; }
.pg-planner-more > summary { cursor: pointer; font-size: 12px; color: #2563eb; padding: 2px 0; }
@media (min-width: 700px) {
  .pg-board { min-width: 0; }
}
@media (min-width: 1000px) {
  .pg-layout { display: grid; grid-template-columns: minmax(0, 1fr) 420px; align-items: start; }
  .pg-main { display: flex; flex-direction: column; gap: 12px; min-width: 0; }
  .pg-side { display: flex; flex-direction: column; gap: 12px; min-width: 0; }
  .pg-act, .pg-extra { order: 0; }
  .pg-rail { order: 1; }
  .pg-extra { order: 2; }
  .pg-board { max-width: max(640px, calc((100vh - 340px) * 1.8)); }
}
@media (min-width: 1600px) {
  .pg-layout { grid-template-columns: 290px minmax(0, 1fr) 420px; }
  .pg-main { grid-column: 2; grid-row: 1; }
  .pg-side { display: contents; }
  .pg-rail { grid-column: 1; grid-row: 1; order: 0; }
  .pg-action { display: flex; flex-direction: column; gap: 12px; grid-column: 3; grid-row: 1; min-width: 0; }
  .pg-act, .pg-extra { order: 0; }
  .pg-board { max-width: max(640px, calc((100vh - 340px) * 1.8)); }
}
@media (min-width: 1600px) and (min-height: 1100px) {
  .pg-root, .pg-layout { height: 100%; min-height: 0; }
  .pg-layout { grid-template-rows: minmax(0, 1fr); align-items: stretch; }
  .pg-main { min-height: 0; overflow-y: auto; }
  .pg-board-card { flex: 1 1 auto; min-height: 440px; }
  .pg-board-wrap { flex: 1 1 0; min-height: 360px; container-type: size; display: flex; align-items: center; justify-content: center; overflow: hidden; }
  .pg-board { flex: none; width: min(100cqw, 100cqh * 1.8); max-width: none; margin: 0; }
  .pg-bottom { flex: none; }
  .pg-rail, .pg-action { min-height: 0; overflow-y: auto; padding-right: 4px; }
}
`;

export function PowerGridView({
  game: rawGame,
  playerId,
  onAction,
}: GameViewProps) {
  // The registry stores every game's state as unknown; this game's reducer owns the shape.
  const game = rawGame as GameRecord<PowerGridState>;
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const { muted, toggleMute } = usePowerGridSounds(game.state, playerId);

  async function send(action: PowerGridAction) {
    setBusy(true);
    setError(null);
    try {
      await onAction(action);
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  }

  const colorOf = (pid: string) =>
    PLAYER_COLORS[
      Math.max(
        0,
        game.players.findIndex((p) => p.id === pid),
      ) % PLAYER_COLORS.length
    ];
  const nameOf = (pid: string) =>
    game.players.find((p) => p.id === pid)?.name ?? pid;

  if (game.status === "waiting" || !game.state) {
    const isHost = playerId === game.createdBy;
    return (
      <section style={{ ...section, maxWidth: 520 }}>
        <h2 style={{ margin: 0 }}>Power Grid</h2>
        <p className="muted" style={{ margin: 0 }}>
          {MIN_PLAYERS} to {MAX_PLAYERS} players. Waiting for the host to start.
        </p>
        <ul style={{ margin: 0 }}>
          {game.players.map((p, i) => (
            <li
              key={p.id}
              style={{
                color: PLAYER_COLORS[i % PLAYER_COLORS.length],
                fontWeight: 600,
              }}
            >
              {p.name}
            </li>
          ))}
        </ul>
        {isHost && (
          <button
            className="btn btn-primary"
            disabled={busy || game.players.length < MIN_PLAYERS}
            onClick={() => send({ type: "start" })}
          >
            Start game
          </button>
        )}
        {error && <p className="error">{error}</p>}
      </section>
    );
  }

  return (
    <PlayingBoard
      game={game}
      s={game.state}
      me={playerId}
      busy={busy}
      error={error}
      send={send}
      colorOf={colorOf}
      nameOf={nameOf}
      muted={muted}
      toggleMute={toggleMute}
    />
  );
}

interface PlayingBoardProps {
  game: GameRecord<PowerGridState>;
  s: PowerGridState;
  me: string;
  busy: boolean;
  error: string | null;
  send: (action: PowerGridAction) => Promise<void>;
  colorOf: (pid: string) => string;
  nameOf: (pid: string) => string;
  muted: boolean;
  toggleMute: () => void;
}

function PlayingBoard({
  game,
  s,
  me,
  busy,
  error,
  send,
  colorOf,
  nameOf,
  muted,
  toggleMute,
}: PlayingBoardProps) {
  const [buildPick, setBuildPick] = useState("");
  // The player's own override of the plants to run, tied to the turn it was made in.
  const [runPick, setRunPick] = useState<{
    key: string;
    plants: number[];
  } | null>(null);
  const autoSent = useRef("");

  const seated = s.order.includes(me);
  const playing = game.status === "started";
  const myTurn = playing && s.current === me && s.pendingScrap === null;
  const myMoney = s.money[me] ?? 0;
  const myOwned = s.plants[me] ?? [];
  const myCities = ownedCities(s, me);
  const row = s.step === 3 ? s.market : s.market.slice(0, 4);
  const future = s.step === 3 ? [] : s.market.slice(4);
  const canNominate = myTurn && s.phase === "auction" && s.auction === null;
  const houseCap = housesAllowed(s.step);

  const canBuildHere = (cityId: string) =>
    myTurn &&
    s.phase === "build" &&
    !(s.houses[cityId] ?? []).includes(me) &&
    (s.houses[cityId] ?? []).length < houseCap &&
    buildCost(s, me, cityId) <= myMoney;

  const buildOptions = CITIES.filter((c) => canBuildHere(c.id))
    .map((c) => ({ id: c.id, cost: buildCost(s, me, c.id) }))
    .sort((a, b) => a.cost - b.cost);
  const pick =
    buildPick && buildOptions.some((o) => o.id === buildPick)
      ? buildPick
      : (buildOptions[0]?.id ?? "");

  const runnable = myOwned
    .filter((op) => storedTotal(op.stored) >= plantData(op.number).inputs)
    .map((op) => op.number);
  const turnKey = `${s.round}:${s.phase}:${s.current ?? ""}`;
  // Plants start selected as the best set. Tapping a card overrides it for this turn.
  const wanted =
    runPick && runPick.key === turnKey
      ? runPick.plants
      : bestPowering(s, me).plants;
  const runSelected = wanted.filter((n) => runnable.includes(n));
  const runCities = runSelected.reduce(
    (sum, n) => sum + plantData(n).cities,
    0,
  );
  const runPowered = Math.min(runCities, myCities.length);

  // Skip steps with nothing to decide: no runnable plant, or no city you can afford.
  const autoPower =
    myTurn && s.phase === "bureaucracy" && runnable.length === 0;
  const autoDone = myTurn && s.phase === "build" && buildOptions.length === 0;
  useEffect(() => {
    if (busy || (!autoPower && !autoDone)) return;
    if (autoSent.current === turnKey) return;
    autoSent.current = turnKey;
    void send(
      autoPower ? { type: "power", plants: [] } : { type: "doneBuild" },
    );
    // send is recreated every render. The ref guard makes this fire once per turn.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoPower, autoDone, busy, turnKey]);

  // The primary action for the current phase lives in the banner. The auction and resource
  // panels carry their own buttons, so the banner stays empty there.
  const bannerActions =
    myTurn && s.phase === "build" ? (
      <button
        className="btn btn-primary"
        disabled={busy}
        onClick={() => send({ type: "doneBuild" })}
      >
        Done building
      </button>
    ) : myTurn && s.phase === "bureaucracy" ? (
      <button
        className="btn btn-primary"
        disabled={busy}
        onClick={() => {
          send({ type: "power", plants: runSelected });
          setRunPick(null);
        }}
      >
        <span
          style={{
            display: "inline-flex",
            flexDirection: "column",
            alignItems: "flex-start",
            lineHeight: 1.25,
          }}
        >
          <span>
            Power{" "}
            {runPowered === 0
              ? "no cities"
              : `${runPowered} ${runPowered === 1 ? "city" : "cities"}`}
            {!s.finalRound && (
              <>
                {" · +"}
                <CoinIcon size={14} /> {payout(runPowered)}
              </>
            )}
          </span>
          <span style={{ fontSize: 11, fontWeight: 500, opacity: 0.85 }}>
            using{" "}
            {runSelected.length === 0
              ? "no plants"
              : `${runSelected.length} plant${runSelected.length === 1 ? "" : "s"}`}
          </span>
        </span>
      </button>
    ) : null;

  return (
    <div className="pg-root">
      <style>{PG_CSS}</style>
      <div className="pg-layout">
        {/* Left: map with a rail, then the plant and resource markets. */}
        <div className="pg-main">
          <section className="pg-board-card" style={section}>
            <div className="pg-board-wrap">
              <PowerGridMap
                state={s}
                me={me}
                colorOf={colorOf}
                nameOf={nameOf}
                canBuild={canBuildHere}
                onBuild={(id) => send({ type: "buildCity", city: id })}
                busy={busy}
              />
            </div>
          </section>

          <div className="pg-bottom">
            <section
              className="pg-resources"
              style={{ ...compactSection, gap: 4 }}
            >
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "baseline",
                  gap: 8,
                }}
              >
                <h3 style={{ margin: 0, fontSize: 15 }}>Resource market</h3>
                <span
                  className="muted"
                  style={{ fontSize: 11 }}
                  title="You buy any amount, one token at a time, cheapest first."
                >
                  Price of one token per box
                </span>
              </div>
              <ResourceMarket spaces={s.resourceSpaces} supply={s.supply} />
            </section>
          </div>
        </div>

        {/* Right: status first, then the current action, then the log and rules. */}
        <aside className="pg-side">
          <div className="pg-action">
            <div className="pg-act">
              <StatusBanner
                state={s}
                me={me}
                playing={playing}
                nameOf={nameOf}
                colorOf={colorOf}
                trailing={<SoundToggle muted={muted} onToggle={toggleMute} />}
              >
                {bannerActions}
              </StatusBanner>

              {error && (
                <p className="error" style={{ margin: 0 }}>
                  {error}
                </p>
              )}

              <section className="pg-market" style={compactSection}>
                <div
                  style={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "baseline",
                    flexWrap: "wrap",
                    gap: 8,
                  }}
                >
                  <h3 style={{ margin: 0, fontSize: 15 }}>
                    Power plant market
                  </h3>
                  <span className="muted" style={{ fontSize: 12 }}>
                    {s.step === 3
                      ? "Step 3: all six can be auctioned"
                      : "Blue: for sale. Faded: next."}
                  </span>
                </div>
                <div className="pg-market-row">
                  <div className="pg-market-group">
                    {row.map((n) => (
                      <PlantCard
                        key={n}
                        n={n}
                        size="sm"
                        row="current"
                        discounted={s.discount === n}
                        minBid={s.discount === n ? 1 : n}
                        disabled={
                          !canNominate ||
                          busy ||
                          myMoney < (s.discount === n ? 1 : n)
                        }
                        onClick={
                          canNominate
                            ? () => send({ type: "nominate", plant: n })
                            : undefined
                        }
                        title={canNominate ? `Auction plant ${n}` : undefined}
                      />
                    ))}
                  </div>
                  {future.length > 0 && (
                    <div className="pg-market-group">
                      {future.map((n) => (
                        <PlantCard key={n} n={n} size="sm" row="future" />
                      ))}
                    </div>
                  )}
                </div>
              </section>

              {game.status === "finished" && s.results && (
                <section style={section}>
                  <h3 style={{ margin: 0 }}>Final scores</h3>
                  <p style={{ margin: 0 }}>
                    Winner:{" "}
                    <strong>
                      {s.results.winners.map(nameOf).join(" and ")}
                    </strong>
                  </p>
                  <table style={{ width: "100%", fontSize: 14 }}>
                    <thead>
                      <tr style={{ textAlign: "left" }}>
                        <th>Player</th>
                        <th>Can power</th>
                        <th>Coins</th>
                      </tr>
                    </thead>
                    <tbody>
                      {s.results.scores.map((sc) => (
                        <tr key={sc.id}>
                          <td>{nameOf(sc.id)}</td>
                          <td>{sc.capacity}</td>
                          <td>{sc.money}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </section>
              )}

              {playing && seated && (
                <>
                  <AuctionPanel
                    state={s}
                    me={me}
                    colorOf={colorOf}
                    nameOf={nameOf}
                    busy={busy}
                    send={send}
                  />
                  <BuyResourcesPanel
                    state={s}
                    me={me}
                    busy={busy}
                    send={send}
                  />
                  {myTurn && s.phase === "resources" && (
                    // The full market sits lower on the page, so show the prices beside the choice.
                    <section style={section}>
                      <h3 style={{ margin: 0, fontSize: 14 }}>Token prices</h3>
                      <ResourceMarket
                        compact
                        spaces={s.resourceSpaces}
                        supply={s.supply}
                      />
                    </section>
                  )}

                  {myTurn && s.phase === "build" && (
                    <section style={section}>
                      {autoDone ? (
                        <div className="muted" style={{ fontSize: 13 }}>
                          You can't afford any city right now, so your build
                          turn ends automatically.
                        </div>
                      ) : (
                        <>
                          <div className="muted" style={{ fontSize: 13 }}>
                            Click a city on the map (hover one to see its cost),
                            or pick one here.
                          </div>
                          <div
                            style={{
                              display: "flex",
                              gap: 8,
                              flexWrap: "wrap",
                            }}
                          >
                            <select
                              value={pick}
                              onChange={(e) => setBuildPick(e.target.value)}
                            >
                              {buildOptions.map((o) => (
                                <option key={o.id} value={o.id}>
                                  {cityName(o.id)} ({o.cost})
                                </option>
                              ))}
                            </select>
                            <button
                              className="btn"
                              disabled={busy || !pick}
                              onClick={() =>
                                send({ type: "buildCity", city: pick })
                              }
                            >
                              Build
                            </button>
                          </div>
                        </>
                      )}
                    </section>
                  )}

                  {myTurn && s.phase === "bureaucracy" && (
                    <section style={section}>
                      {autoPower ? (
                        <div className="muted" style={{ fontSize: 13 }}>
                          {myOwned.length === 0
                            ? "You have no plants to run, so this step is skipped automatically."
                            : "None of your plants has enough tokens to run, so this step is skipped automatically."}
                        </div>
                      ) : (
                        <>
                          <div className="muted" style={{ fontSize: 13 }}>
                            {s.finalRound
                              ? "Your best plants are selected. Tap a card to change it. Money doesn't count."
                              : "Your best plants are selected. Tap a card to change it, then run."}
                          </div>
                          <div
                            style={{
                              display: "flex",
                              gap: 10,
                              flexWrap: "wrap",
                            }}
                          >
                            {myOwned.map((op) => {
                              const ok = runnable.includes(op.number);
                              const on = runSelected.includes(op.number);
                              return (
                                <PlantCard
                                  key={op.number}
                                  n={op.number}
                                  size="sm"
                                  stored={storedTotal(op.stored)}
                                  selected={on}
                                  disabled={!ok || busy}
                                  onClick={() =>
                                    setRunPick({
                                      key: turnKey,
                                      plants: on
                                        ? runSelected.filter(
                                            (n) => n !== op.number,
                                          )
                                        : [...runSelected, op.number],
                                    })
                                  }
                                  title={
                                    ok
                                      ? `Run plant ${op.number}`
                                      : `Plant ${op.number} needs more tokens`
                                  }
                                />
                              );
                            })}
                          </div>
                          <div style={{ fontSize: 14 }}>
                            Powers <strong>{runPowered}</strong> of{" "}
                            {myCities.length} cities
                          </div>
                        </>
                      )}
                    </section>
                  )}
                </>
              )}
            </div>
            <div className="pg-extra">
              <section style={compactSection}>
                <h3 style={{ margin: 0, fontSize: 15 }}>Log</h3>
                <RecentLog log={s.log} colorOf={colorOf} />
              </section>

              <section style={{ ...section, padding: 10 }}>
                <PowerGridRules />
              </section>
            </div>
          </div>
          <div className="pg-rail">
            <section style={compactSection}>
              <h3 style={{ margin: 0, fontSize: 15 }}>Players</h3>
              <PlayersPanel
                compact
                state={s}
                me={me}
                nameOf={nameOf}
                colorOf={colorOf}
                renderExtra={(pid) => <IncomeChip state={s} pid={pid} />}
              />
            </section>
            {seated && (
              <section style={compactSection}>
                <h3 style={{ margin: 0, fontSize: 15 }}>Payment table</h3>
                <IncomePlanner state={s} pid={me} chartOnly />
              </section>
            )}
          </div>
        </aside>
      </div>
    </div>
  );
}
