// Path helpers for the Power Grid map.
import { CITIES, EDGES } from "./map/map";

const REGION_OF: Record<string, string> = Object.fromEntries(
  CITIES.map((c) => [c.id, c.region]),
);

export interface PathResult {
  path: string[]; // city ids in order, starting at the nearest source and ending at the target
  cost: number; // total connection cost; Infinity (with an empty path) if unreachable or no sources
}

// Key for an undirected edge, independent of direction.
export function edgeKey(a: string, b: string): string {
  return a < b ? `${a}|${b}` : `${b}|${a}`;
}

const EDGE_COST: Record<string, number> = {};
const ADJ: Record<string, { to: string; cost: number }[]> = {};
for (const e of EDGES) {
  EDGE_COST[edgeKey(e.from, e.to)] = e.cost;
  (ADJ[e.from] ??= []).push({ to: e.to, cost: e.cost });
  (ADJ[e.to] ??= []).push({ to: e.from, cost: e.cost });
}

// Cost of the direct link between two cities, or undefined if they aren't linked.
export function edgeCost(a: string, b: string): number | undefined {
  return EDGE_COST[edgeKey(a, b)];
}

// Cheapest route from any of `from` to `to` (Dijkstra). A target that is already a source costs 0.
export function cheapestPath(
  from: string[],
  to: string,
  regions?: string[],
): PathResult {
  const inPlay = (id: string) => !regions || regions.includes(REGION_OF[id]);
  const none: PathResult = { path: [], cost: Infinity };
  if (from.length === 0 || !(to in ADJ)) return none;

  const dist: Record<string, number> = {};
  const prev: Record<string, string | null> = {};
  const done: Record<string, boolean> = {};
  for (const id of Object.keys(ADJ)) dist[id] = Infinity;
  for (const s of from) {
    if (s in dist) {
      dist[s] = 0;
      prev[s] = null;
    }
  }

  for (;;) {
    let best: string | null = null;
    for (const id of Object.keys(dist)) {
      if (
        !done[id] &&
        dist[id] < Infinity &&
        (best === null || dist[id] < dist[best])
      )
        best = id;
    }
    if (best === null) break;
    if (best === to) break;
    done[best] = true;
    for (const n of ADJ[best]) {
      if (!inPlay(n.to)) continue;
      if (dist[best] + n.cost < dist[n.to]) {
        dist[n.to] = dist[best] + n.cost;
        prev[n.to] = best;
      }
    }
  }

  if (dist[to] === Infinity) return none;
  const path: string[] = [];
  for (let at: string | null = to; at !== null; at = prev[at] ?? null)
    path.unshift(at);
  return { path, cost: dist[to] };
}
