import { plantCapacity, plantData, storedTotal } from "./plants";
import { quote, RESOURCE_SPACES, tokensIn } from "./resources";
import {
  OwnedPlant,
  PowerGridAction,
  PowerGridState,
  Resource,
  RESOURCES,
  Stock,
} from "./types";

type Spaces = Record<Resource, number[]>;
export type Pending = Partial<Record<Resource, number>>;

export interface CostPreview {
  cost: number;
  // Price of each token bought, cheapest first.
  prices: number[];
}

// What `units` tokens of a resource would cost right now, with the price of each token.
// Returns null if the market does not have that many.
export function previewCost(
  spaces: Spaces,
  r: Resource,
  units: number,
): CostPreview | null {
  if (units <= 0) return { cost: 0, prices: [] };
  const q = quote(spaces, r, units);
  if (!q) return null;
  const prices: number[] = [];
  q.takes.forEach((t, i) => {
    for (let k = 0; k < t; k++) prices.push(RESOURCE_SPACES[r][i]);
  });
  return { cost: q.cost, prices };
}

// "1 + 1 + 2 = 4" style text. Empty when nothing is bought.
export function costBreakdown(prices: number[]): string {
  if (prices.length === 0) return "";
  const total = prices.reduce((a, b) => a + b, 0);
  return prices.length === 1 ? `${total}` : `${prices.join(" + ")} = ${total}`;
}

// Prices of the next `count` tokens after `skip` tokens have been taken.
export function upcomingPrices(
  spaces: Spaces,
  r: Resource,
  skip: number,
  count: number,
): number[] {
  const all = previewCost(
    spaces,
    r,
    Math.min(tokensIn(spaces, r), skip + count),
  );
  return all ? all.prices.slice(skip) : [];
}

// Most tokens that fit all limits: room in the plant, stock in the market and money.
export function maxAffordable(
  spaces: Spaces,
  r: Resource,
  money: number,
  room: number,
): number {
  const limit = Math.min(Math.max(0, room), tokensIn(spaces, r));
  let best = 0;
  for (let n = 1; n <= limit; n++) {
    const p = previewCost(spaces, r, n);
    if (!p || p.cost > money) break;
    best = n;
  }
  return best;
}

export function pendingTotal(p: Pending): number {
  return RESOURCES.reduce((sum, r) => sum + (p[r] ?? 0), 0);
}

export function pendingCost(spaces: Spaces, p: Pending): number | null {
  let total = 0;
  for (const r of RESOURCES) {
    const n = p[r] ?? 0;
    if (n === 0) continue;
    const c = previewCost(spaces, r, n);
    if (!c) return null;
    total += c.cost;
  }
  return total;
}

export interface AddCheck {
  ok: boolean;
  // Why a token cannot be added. Empty when ok.
  reason: string;
}

// Can one more token of `r` be added to the pending purchase for this plant?
export function canAddToken(
  spaces: Spaces,
  owned: OwnedPlant,
  pending: Pending,
  r: Resource,
  money: number,
): AddCheck {
  const data = plantData(owned.number);
  if (!data.fuel.includes(r))
    return { ok: false, reason: `Plant ${owned.number} can't burn ${r}` };
  const room =
    plantCapacity(data) - storedTotal(owned.stored) - pendingTotal(pending);
  if (room <= 0) return { ok: false, reason: "Plant is full" };
  const want = (pending[r] ?? 0) + 1;
  const p = previewCost(spaces, r, want);
  if (!p) return { ok: false, reason: `No more ${r} in the market` };
  const others = pendingCost(spaces, { ...pending, [r]: 0 }) ?? 0;
  if (others + p.cost > money) return { ok: false, reason: "Not enough money" };
  return { ok: true, reason: "" };
}

export type SlotState = {
  state: "stored" | "pending" | "empty";
  resource?: Resource;
};

// Token slots for a plant: stored tokens, then pending ones, then empty room.
export function slotLayout(
  capacity: number,
  stored: Stock,
  pending: Pending,
): SlotState[] {
  const slots: SlotState[] = [];
  for (const r of RESOURCES)
    for (let i = 0; i < stored[r]; i++)
      slots.push({ state: "stored", resource: r });
  for (const r of RESOURCES)
    for (let i = 0; i < (pending[r] ?? 0); i++)
      slots.push({ state: "pending", resource: r });
  while (slots.length < capacity) slots.push({ state: "empty" });
  return slots.slice(0, capacity);
}

// The "fill to capacity" purchase. For hybrids it greedily adds whichever fuel has the cheaper next token.
export function fillPlan(
  spaces: Spaces,
  owned: OwnedPlant,
  money: number,
  start: Pending = {},
): Pending {
  const out: Pending = { ...start };
  for (let guard = 0; guard < 100; guard++) {
    let best: Resource | null = null;
    let bestPrice = Infinity;
    for (const r of plantData(owned.number).fuel) {
      if (!canAddToken(spaces, owned, out, r, money).ok) continue;
      const price = upcomingPrices(spaces, r, out[r] ?? 0, 1)[0];
      if (price !== undefined && price < bestPrice) {
        best = r;
        bestPrice = price;
      }
    }
    if (!best) break;
    out[best] = (out[best] ?? 0) + 1;
  }
  return out;
}

// One buyResource action per resource type with a positive amount.
export function purchaseActions(
  plant: number,
  pending: Pending,
): PowerGridAction[] {
  return RESOURCES.filter((r) => (pending[r] ?? 0) > 0).map((r) => ({
    type: "buyResource" as const,
    plant,
    resource: r,
    units: pending[r]!,
  }));
}

// Plants that could not run next round for lack of tokens, with what they have and need.
export function shortPlants(
  plants: OwnedPlant[],
): { plant: number; have: number; need: number }[] {
  return plants
    .map((p) => ({
      plant: p.number,
      have: storedTotal(p.stored),
      need: plantData(p.number).inputs,
    }))
    .filter((x) => x.need > 0 && x.have < x.need);
}

// True when the player could not buy a single token: no fuel plant with room, nothing in the market
// that their plants burn, or not enough money for even the cheapest token.
export function nothingToBuy(state: PowerGridState, me: string): boolean {
  const money = state.money[me] ?? 0;
  return !(state.plants[me] ?? []).some((owned) =>
    plantData(owned.number).fuel.some(
      (r) => canAddToken(state.resourceSpaces, owned, {}, r, money).ok,
    ),
  );
}
